package com.bswmagicgaming.fiveactive;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import lombok.Getter;
import net.runelite.api.Quest;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;
import static net.runelite.api.Quest.*;

/**
 * Every boss the mode knows about, with its unlock requirements.
 * Which bosses are actually rollable (and at what total KC) is decided by {@link BossTiers}.
 *
 * Each boss is declared as {@code NAME("Display name", options...)}. Options, all optional:
 * <ul>
 * <li>{@code quest(...)} quests that must be complete before the boss can be rolled</li>
 * <li>{@code slayer(n)} Slayer level needed to fight it</li>
 * <li>{@code kc(...)} in-game kill count names, if not the same as the display name. These are the names from the
 * "Your ___ kill count is: N" message. A boss with several modes/counters lists each one, and kills on any of them count</li>
 * <li>{@code oneKill()} completed after a single kill instead of {@link Rules#KILLS_TO_COMPLETE_BOSS} (wave bosses, and bosses that are slow to get another attempt at)</li>
 * <li>{@code hiscore(...)} the hiscores entry to take the panel icon from, only needed when it can't be matched by name</li>
 * </ul>
 *
 * Search for "FA-VERIFY" to find entries that need double-checking.
 */
@Getter
enum Boss
{
	// --- No requirements ---
	BRYOPHYTA("Bryophyta"),
	CHAOS_ELEMENTAL("Chaos Elemental"),
	CHAOS_FANATIC("Chaos Fanatic"),
	CHAMBERS_OF_XERIC("Chambers of Xeric", kc("Chambers of Xeric", "Chambers of Xeric Challenge Mode")),
	CORPOREAL_BEAST("Corporeal Beast"),
	CRAZY_ARCHAEOLOGIST("Crazy Archaeologist"),
	DAGANNOTH_KINGS("Dagannoth Kings", kc("Dagannoth Rex", "Dagannoth Prime", "Dagannoth Supreme")),
	GIANT_MOLE("Giant Mole"),
	KALPHITE_QUEEN("Kalphite Queen"),
	KING_BLACK_DRAGON("King Black Dragon"),
	OBOR("Obor"),
	ROYAL_TITANS("Royal Titans"),
	SARACHNIS("Sarachnis"),
	SCORPIA("Scorpia"),
	SCURRIUS("Scurrius"),
	TEMPOROSS("Tempoross"),
	WINTERTODT("Wintertodt"),

	// --- Wilderness bosses ---
	ARTIO("Artio"),
	CALLISTO("Callisto"),
	CALVARION("Calvar'ion"),
	SPINDEL("Spindel"),
	VENENATIS("Venenatis"),
	VETION("Vet'ion"),

	// --- One-kill bosses (done after a single kill) ---
	// Wave bosses: one completion is a whole run of waves
	FIGHT_CAVES("Fight Caves", kc("TzTok-Jad"), oneKill()),
	INFERNO("Inferno", kc("TzKal-Zuk"), oneKill()),
	FORTIS_COLOSSEUM("Fortis Colosseum", kc("Sol Heredit"), oneKill(), quest(CHILDREN_OF_THE_SUN)),
	// Slow to get another attempt at (a farming patch to grow, a rare casket, a totem to piece together)
	HESPORI("Hespori", oneKill()),
	MIMIC("Mimic", oneKill()),
	SKOTIZO("Skotizo", oneKill()),

	// --- God Wars Dungeon ---
	COMMANDER_ZILYANA("Commander Zilyana", quest(DEATH_PLATEAU)),
	GENERAL_GRAARDOR("General Graardor", quest(DEATH_PLATEAU)),
	KREEARRA("Kree'arra", quest(DEATH_PLATEAU)),
	KRIL_TSUTSAROTH("K'ril Tsutsaroth", quest(DEATH_PLATEAU)),
	NEX("Nex", quest(THE_FROZEN_DOOR)),

	// --- Slayer bosses ---
	SHELLBANE_GRYPHON("Shellbane Gryphon", slayer(51), quest(TROUBLED_TORTUGANS)),
	GROTESQUE_GUARDIANS("Grotesque Guardians", slayer(75)),
	ABYSSAL_SIRE("Abyssal Sire", slayer(85), quest(ENTER_THE_ABYSS)),
	KRAKEN("Kraken", slayer(87)),
	CERBERUS("Cerberus", slayer(91)),
	ARAXXOR("Araxxor", slayer(92)),
	THERMONUCLEAR_SMOKE_DEVIL("Thermonuclear Smoke Devil", slayer(93)),
	ALCHEMICAL_HYDRA("Alchemical Hydra", slayer(95)),

	// --- Quest-locked bosses ---
	AMOXLIATL("Amoxliatl", quest(THE_HEART_OF_DARKNESS)),
	BARROWS("Barrows", kc("Barrows Chests"), quest(PRIEST_IN_PERIL)),
	BRUTUS("Brutus", quest(THE_IDES_OF_MILK)),
	DERANGED_ARCHAEOLOGIST("Deranged Archaeologist", quest(BONE_VOYAGE)),
	DOOM_OF_MOKHAIOTL("Doom of Mokhaiotl", quest(THE_FINAL_DAWN)), // FA-VERIFY: kills are read from a varp, not chat (see ProgressionListener)
	DUKE_SUCELLUS("Duke Sucellus", quest(DESERT_TREASURE_II__THE_FALLEN_EMPIRE)),
	PERILOUS_MOONS("Perilous Moons", kc("Lunar Chest"), quest(Quest.PERILOUS_MOONS), hiscore(HiscoreSkill.LUNAR_CHESTS)),
	PHANTOM_MUSPAH("Phantom Muspah", quest(SECRETS_OF_THE_NORTH)),
	THE_GAUNTLET("The Gauntlet", kc("Gauntlet", "Corrupted Gauntlet"), quest(SONG_OF_THE_ELVES)),
	THE_HUEYCOATL("The Hueycoatl", kc("Hueycoatl"), quest(CHILDREN_OF_THE_SUN)),
	THE_LEVIATHAN("The Leviathan", quest(DESERT_TREASURE_II__THE_FALLEN_EMPIRE)),
	THE_NIGHTMARE("The Nightmare", kc("Nightmare", "Phosani's Nightmare"), quest(PRIEST_IN_PERIL)),
	THE_WHISPERER("The Whisperer", quest(DESERT_TREASURE_II__THE_FALLEN_EMPIRE)),
	THEATRE_OF_BLOOD("Theatre of Blood", kc("Theatre of Blood", "Theatre of Blood Hard Mode", "Theatre of Blood Entry Mode"), quest(PRIEST_IN_PERIL)),
	TOMBS_OF_AMASCUT("Tombs of Amascut", kc("Tombs of Amascut", "Tombs of Amascut Entry Mode", "Tombs of Amascut Expert Mode"), quest(BENEATH_CURSED_SANDS)),
	VARDORVIS("Vardorvis", quest(DESERT_TREASURE_II__THE_FALLEN_EMPIRE)),
	VORKATH("Vorkath", quest(DRAGON_SLAYER_II)),
	YAMA("Yama", quest(A_KINGDOM_DIVIDED)),
	ZALCANO("Zalcano", quest(SONG_OF_THE_ELVES)),
	ZULRAH("Zulrah", quest(REGICIDE)),

	// --- Requirements unknown ---
	MAD_ANGEL("Mad Angel", quest(FALLEN_FROM_GRACE)),
	MAGGOT_KING("Maggot King", quest(THE_BLOOD_MOON_RISES)), // FA-VERIFY: check whether it has a kill count chat message
	;

	/** Name shown in the side panel. */
	private final String displayName;
	/** In-game kill count counter names for this boss (see class docs). */
	private final List<String> kcNames;
	/** Slayer level needed to fight this boss, or 0. */
	private final int slayerLevel;
	/** Quests that must be complete before this boss can be rolled. */
	private final List<Quest> requiredQuests;
	/** Kills needed to complete this boss once it is active. */
	private final int killsToComplete;
	/** Hiscores entry whose 25x25 sprite is used as this boss's icon, or null if there isn't one. */
	private final HiscoreSkill hiscore;

	Boss(String displayName, Option... options)
	{
		String[] kcNames = {displayName};
		int slayerLevel = 0;
		Quest[] quests = {};
		int killsToComplete = Rules.KILLS_TO_COMPLETE_BOSS;
		HiscoreSkill hiscore = null;
		for (Option option : options)
		{
			if (option.hiscore != null)
			{
				hiscore = option.hiscore;
			}
			if (option.kcNames != null)
			{
				kcNames = option.kcNames;
			}
			if (option.quests != null)
			{
				quests = option.quests;
			}
			slayerLevel = Math.max(slayerLevel, option.slayerLevel);
			if (option.killsToComplete > 0)
			{
				killsToComplete = option.killsToComplete;
			}
		}
		this.displayName = displayName;
		this.kcNames = Collections.unmodifiableList(Arrays.asList(kcNames));
		this.slayerLevel = slayerLevel;
		this.requiredQuests = Collections.unmodifiableList(Arrays.asList(quests));
		this.killsToComplete = killsToComplete;
		this.hiscore = hiscore != null ? hiscore : findHiscore(displayName, kcNames);
	}

	/** Matches a hiscores boss entry by display name or any kill count name, ignoring case, punctuation and "The". */
	private static HiscoreSkill findHiscore(String displayName, String[] kcNames)
	{
		for (HiscoreSkill skill : HiscoreSkill.values())
		{
			if (skill.getType() != HiscoreSkillType.BOSS)
			{
				continue;
			}
			String hiscoreName = matchKey(skill.getName());
			if (hiscoreName.equals(matchKey(displayName)))
			{
				return skill;
			}
			for (String kcName : kcNames)
			{
				if (hiscoreName.equals(matchKey(kcName)))
				{
					return skill;
				}
			}
		}
		return null;
	}

	private static String matchKey(String name)
	{
		return name.toLowerCase().replaceFirst("^the ", "").replaceAll("[^a-z0-9]", "");
	}

	/** One declaration option; see the class docs. */
	private static final class Option
	{
		private String[] kcNames;
		private Quest[] quests;
		private int slayerLevel;
		private int killsToComplete;
		private HiscoreSkill hiscore;
	}

	private static Option kc(String... names)
	{
		Option option = new Option();
		option.kcNames = names;
		return option;
	}

	private static Option quest(Quest... quests)
	{
		Option option = new Option();
		option.quests = quests;
		return option;
	}

	private static Option slayer(int level)
	{
		Option option = new Option();
		option.slayerLevel = level;
		return option;
	}

	private static Option oneKill()
	{
		Option option = new Option();
		option.killsToComplete = 1;
		return option;
	}

	private static Option hiscore(HiscoreSkill skill)
	{
		Option option = new Option();
		option.hiscore = skill;
		return option;
	}

	/** Normalises a kill count counter name so chat text and our names compare reliably. */
	static String normalizeKcName(String name)
	{
		return name.toLowerCase().replace(":", "").trim();
	}

	/** Finds the boss owning an in-game kill count counter name, or null. */
	static Boss fromKcName(String kcName)
	{
		String normalized = normalizeKcName(kcName);
		for (Boss boss : values())
		{
			for (String name : boss.kcNames)
			{
				if (normalizeKcName(name).equals(normalized))
				{
					return boss;
				}
			}
		}
		return null;
	}
}

package com.bswmagicgaming.fiveactive;

import com.google.common.collect.ImmutableList;
import java.util.List;
import lombok.Value;
import static com.bswmagicgaming.fiveactive.Boss.*;

/**
 * The boss pool, split into tiers that unlock as the player's total boss KC grows.
 * Edit the milestones and boss lists here to rebalance progression.
 * A boss that is not in any tier can never be rolled.
 */
final class BossTiers
{
	@Value
	static class Tier
	{
		/** Total boss KC needed before this tier's bosses join the pool (0 = available from the start). */
		int killsRequired;
		List<Boss> bosses;
	}

	static final List<Tier> TIERS = ImmutableList.of(
		new Tier(0, ImmutableList.of(
			BARROWS,
			BRUTUS,
			OBOR,
			BRYOPHYTA,
			SCURRIUS,
			GIANT_MOLE,
			AMOXLIATL,
			CRAZY_ARCHAEOLOGIST,
			DERANGED_ARCHAEOLOGIST,
			CHAOS_FANATIC,
			TEMPOROSS,
			WINTERTODT,
			HESPORI,
			DAGANNOTH_KINGS
		)),
		new Tier(100, ImmutableList.of(
			SARACHNIS,
			SCORPIA,
			PERILOUS_MOONS,
			CHAOS_ELEMENTAL,
			FIGHT_CAVES,
			SPINDEL,
			ARTIO,
			KING_BLACK_DRAGON,
			ROYAL_TITANS,
			THE_HUEYCOATL,
			CALVARION,
			SKOTIZO,
			KALPHITE_QUEEN,
			MIMIC,
			MAD_ANGEL,
			ZALCANO,
			SHELLBANE_GRYPHON
		)),
		new Tier(500, ImmutableList.of(
			THE_GAUNTLET,
			VORKATH,
			ZULRAH,
			VETION,
			TOMBS_OF_AMASCUT,
			DOOM_OF_MOKHAIOTL,
			PHANTOM_MUSPAH,
			GROTESQUE_GUARDIANS,
			ABYSSAL_SIRE,
			KRAKEN,
			CERBERUS,
			ARAXXOR,
			THERMONUCLEAR_SMOKE_DEVIL,
			ALCHEMICAL_HYDRA
		)),
		new Tier(1000, ImmutableList.of(
			GENERAL_GRAARDOR,
			KREEARRA,
			KRIL_TSUTSAROTH,
			COMMANDER_ZILYANA,
			DUKE_SUCELLUS,
			MAGGOT_KING,
			CHAMBERS_OF_XERIC,
			YAMA,
			VENENATIS,
			CALLISTO
		)),
		new Tier(2500, ImmutableList.of(
			THEATRE_OF_BLOOD,
			INFERNO,
			FORTIS_COLOSSEUM,
			THE_WHISPERER,
			THE_LEVIATHAN,
			VARDORVIS,
			THE_NIGHTMARE,
			CORPOREAL_BEAST,
			NEX
		))
	);

	/** The first tier the player has not reached yet, or null once everything is unlocked. */
	static Tier nextLockedTier(int totalKc)
	{
		for (Tier tier : TIERS)
		{
			if (totalKc < tier.getKillsRequired())
			{
				return tier;
			}
		}
		return null;
	}

	/** The tier a boss belongs to, or null if it is not in the pool at all. */
	static Tier tierOf(Boss boss)
	{
		for (Tier tier : TIERS)
		{
			if (tier.getBosses().contains(boss))
			{
				return tier;
			}
		}
		return null;
	}

	private BossTiers()
	{
	}
}

package com.bswmagicgaming.fiveactive;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
enum Category
{
	SKILLS("Skills", "skill", "skills"),
	BOSSES("Bosses", "boss", "bosses"),
	QUESTS("Quests", "quest", "quests");

	private final String title;
	private final String singular;
	private final String plural;

	String noun(int count)
	{
		return count == 1 ? singular : plural;
	}
}

package com.bswmagicgaming.fiveactive;

import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(FiveActiveConfig.GROUP)
public interface FiveActiveConfig extends Config
{
	String GROUP = "fiveactive";

	@Getter
	@RequiredArgsConstructor
	enum KcMode
	{
		SINCE_START("Since mode start"),
		LIFETIME("Lifetime");

		private final String label;

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigItem(
		keyName = "kcMode",
		name = "Total KC counts",
		description = "What counts towards the boss tier unlocks.<br>"
			+ "Lifetime: your real kill counts (open the Boss Kill Log in your POH with Chat Commands enabled to sync).<br>"
			+ "Since mode start: only kills of active bosses during this run (for starting the mode on an existing account).",
		position = 1
	)
	default KcMode kcMode()
	{
		// Most runs start on a fresh account, where lifetime and mode KC are the same thing
		return KcMode.LIFETIME;
	}

	@ConfigItem(
		keyName = "dimSkillsTab",
		name = "Dim inactive skills",
		description = "Darken inactive skills in the skills tab.",
		position = 4
	)
	default boolean dimSkillsTab()
	{
		return true;
	}

	@ConfigItem(
		keyName = "dimQuestList",
		name = "Dim inactive quests",
		description = "Grey out inactive quests in the quest list.",
		position = 5
	)
	default boolean dimQuestList()
	{
		return true;
	}

	@ConfigItem(
		keyName = "slotMachine",
		name = "Roll animation",
		description = "Spin newly rolled skills, bosses and quests in like a slot machine.<br>Turn off to show results instantly.",
		position = 6
	)
	default boolean slotMachine()
	{
		return true;
	}

	@ConfigItem(
		keyName = "sounds",
		name = "Sounds",
		description = "Play the plugin's sounds: the roll animation, the panel's login and logout animations,<br>"
			+ "rule-break warnings, and earning Shuffles or unlocking boss tiers.",
		position = 7
	)
	default boolean sounds()
	{
		return true;
	}

	@Getter
	@RequiredArgsConstructor
	enum OverlayMode
	{
		PANEL_CLOSED("When panel is closed"),
		ALWAYS("Always"),
		OFF("Never");

		private final String label;

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigSection(name = "Overlay", description = "The at-a-glance overlay beside the inventory", position = 50)
	String OVERLAY_SECTION = "overlay";

	@ConfigItem(
		keyName = "overlayMode",
		name = "Show overlay",
		description = "An at-a-glance overlay of your active quests, skills and bosses, beside the inventory.<br>"
			+ "Alt-drag it to move it.",
		position = 1,
		section = OVERLAY_SECTION
	)
	default OverlayMode overlayMode()
	{
		return OverlayMode.PANEL_CLOSED;
	}

	@Getter
	@RequiredArgsConstructor
	enum OverlayStyle
	{
		DETAILED("Detailed"),
		COMPACT("Compact");

		private final String label;

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigItem(
		keyName = "overlayStyle",
		name = "Style",
		description = "Detailed: names with progress beside them.<br>"
			+ "Compact: just icons with a progress bar under each, for small spaces. Hover an icon for its name.",
		position = 2,
		section = OVERLAY_SECTION
	)
	default OverlayStyle overlayStyle()
	{
		return OverlayStyle.DETAILED;
	}

	@ConfigItem(
		keyName = "overlayQuests",
		name = "Quests",
		description = "Show your active quests in the overlay.",
		position = 3,
		section = OVERLAY_SECTION
	)
	default boolean overlayQuests()
	{
		return true;
	}

	@ConfigItem(
		keyName = "overlaySkills",
		name = "Skills",
		description = "Show your active skills in the overlay.",
		position = 4,
		section = OVERLAY_SECTION
	)
	default boolean overlaySkills()
	{
		return true;
	}

	@ConfigItem(
		keyName = "overlayBosses",
		name = "Bosses",
		description = "Show your active bosses in the overlay.",
		position = 5,
		section = OVERLAY_SECTION
	)
	default boolean overlayBosses()
	{
		return true;
	}

	@ConfigItem(
		keyName = "tierFireworks",
		name = "Tier unlock fireworks",
		description = "Set off level-up fireworks on your character when you unlock a boss tier (only you see them).",
		position = 8
	)
	default boolean tierFireworks()
	{
		return true;
	}

	@ConfigItem(
		keyName = "tierBanner",
		name = "Tier unlock banner",
		description = "Show a big \"Tier unlocked!\" banner in the middle of the game view when you unlock a boss tier.",
		position = 9
	)
	default boolean tierBanner()
	{
		return true;
	}

	@Getter
	@RequiredArgsConstructor
	enum BossPoolStyle
	{
		ICONS("Icons"),
		LIST("List");

		private final String label;

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigItem(
		keyName = "bossPoolStyle",
		name = "Boss pool style",
		description = "Icons: a grid of boss icons per tier (hover for names).<br>List: every boss by name.",
		position = 8
	)
	default BossPoolStyle bossPoolStyle()
	{
		return BossPoolStyle.ICONS;
	}

	@Getter
	@RequiredArgsConstructor
	enum HistoryGrouping
	{
		DAY("Day"),
		WEEK("Week"),
		MONTH("Month"),
		YEAR("Year");

		private final String label;
	}

	String HISTORY_GROUPING_KEY = "historyGrouping";

	/** How the History view groups entries (a view preference, set in the panel). */
	@ConfigItem(keyName = HISTORY_GROUPING_KEY, name = "", description = "", hidden = true)
	default HistoryGrouping historyGrouping()
	{
		return HistoryGrouping.DAY;
	}

	String HISTORY_OLDEST_FIRST_KEY = "historyOldestFirst";

	/** Whether the History view reads from the start of the run instead of from the latest. */
	@ConfigItem(keyName = HISTORY_OLDEST_FIRST_KEY, name = "", description = "", hidden = true)
	default boolean historyOldestFirst()
	{
		return false;
	}

	String SHORTCUTS_KEY = "shortcutsEnabled";

	/** The undocumented shortcuts (see HiddenKeys): off until switched on with the ::fiveactive keys chat command. */
	@ConfigItem(keyName = SHORTCUTS_KEY, name = "", description = "", hidden = true)
	default boolean shortcutsEnabled()
	{
		return false;
	}

	String COLLAPSED_TIERS_KEY = "collapsedTiers";

	/** Comma-separated boss pool tiers (by KC milestone) the user has collapsed. */
	@ConfigItem(keyName = COLLAPSED_TIERS_KEY, name = "", description = "", hidden = true)
	default String collapsedTiers()
	{
		return "";
	}

	String COLLAPSED_SECTIONS_KEY = "collapsedSections";

	/**
	 * Comma-separated side panel sections the user has collapsed. The boss pool starts collapsed (it's extra
	 * detail); after that the panel remembers what the user left open. "NONE" means nothing is collapsed:
	 * RuneLite treats an empty value as unset, which would bring this default back.
	 */
	@ConfigItem(keyName = COLLAPSED_SECTIONS_KEY, name = "", description = "", hidden = true)
	default String collapsedSections()
	{
		return "POOL";
	}

	@ConfigSection(name = "Backups", description = "Save codes and backups of your run", position = 90, closedByDefault = true)
	String BACKUP_SECTION = "backups";

	String COPY_SAVE_CODE_KEY = "copySaveCode";
	String SAVE_FILE_KEY = "saveRunToFile";
	String RESTORE_RUN_KEY = "restoreRun";
	String OPEN_BACKUPS_KEY = "openBackupFolder";

	/** Acts as a button. */
	@ConfigItem(
		keyName = COPY_SAVE_CODE_KEY,
		name = "Copy save code (tick)",
		description = "Copies your whole run and its History to the clipboard as one line of text.<br>"
			+ "You must be logged in to the account whose run you want to copy.<br>"
			+ "Keep it somewhere safe: Restore a backup can bring the run back from it, even on another computer.",
		section = BACKUP_SECTION,
		position = 1
	)
	default boolean copySaveCode()
	{
		return false;
	}

	/** Acts as a button. */
	@ConfigItem(
		keyName = SAVE_FILE_KEY,
		name = "Save run to file (tick)",
		description = "Saves your whole run and its History as a small text file, the same as a save code.<br>"
			+ "Handy for sharing (e.g. on Discord, where a save code is too long to paste) or keeping a copy.<br>"
			+ "You must be logged in to the account whose run you want to save.",
		section = BACKUP_SECTION,
		position = 2
	)
	default boolean saveRunToFile()
	{
		return false;
	}

	/** Acts as a button. */
	@ConfigItem(
		keyName = RESTORE_RUN_KEY,
		name = "Restore a backup (tick)",
		description = "Brings back an earlier copy of an account's run. A copy is saved each time you log in,<br>"
			+ "or you can load a save file or paste a save code. Your run as it is now is backed up first.<br>"
			+ "You must be logged in to the account you want to restore.",
		section = BACKUP_SECTION,
		position = 3
	)
	default boolean restoreRun()
	{
		return false;
	}

	/** Acts as a button. */
	@ConfigItem(
		keyName = OPEN_BACKUPS_KEY,
		name = "Copy backup folder location (tick)",
		description = "Copies where this account's backups and History log are kept.<br>"
			+ "Paste it into File Explorer's address bar to open the folder.",
		section = BACKUP_SECTION,
		position = 4
	)
	default boolean openBackupFolder()
	{
		return false;
	}

}

package com.bswmagicgaming.fiveactive;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.BackgroundComponent;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.ImageUtil;

/**
 * The run at a glance, for when the side panel is closed: every active quest, skill and boss with its progress.
 * Sits in the bottom-right corner of the game view (beside the inventory in resizable mode); Alt-drag to move it.
 *
 * Progress is shown, not spelled out: skills and bosses fill a row of green squares, and quests are coloured like
 * the in-game quest list (red not started, yellow in progress, green done), which users already know.
 */
class FiveActiveOverlay extends Overlay
{
	private static final int WIDTH = 200;
	private static final int PAD = 6;
	private static final int ROW_HEIGHT = 18;
	private static final int ICON = 16;
	private static final int PIP = 6;
	private static final int PIP_GAP = 2;
	private static final int SECTION_GAP = 5;
	/** How long a newly revealed row takes to pop in (matching the panel's reel landing). */
	static final int POP_MS = 450;
	/** The green flash when a slot is finished: a little longer than a reveal, it's a celebration. */
	static final int COMPLETE_POP_MS = 700;

	// Compact style: a row of icon cells per section, each with a progress bar underneath
	private static final int CELL = 25;
	private static final int CELL_GAP = 3;
	private static final int BAR_HEIGHT = 4;
	private static final int CELL_BLOCK = CELL + 2 + BAR_HEIGHT;
	private static final int COMPACT_WIDTH = 2 * PAD + Rules.SLOTS * CELL + (Rules.SLOTS - 1) * CELL_GAP;
	/** A step lighter than the overlay background, so dark sprites (spiders, demons) stand out from it. */
	private static final Color CELL_BACK = new Color(125, 110, 90, 110);
	/** Green tick on a finished cell. 'o' green, 'k' black edge. */
	private static final String[] TICK = {
		"......kk",
		".....kok",
		"k...kok.",
		"kok.kok.",
		".kokok..",
		"..kok...",
		"...k....",
	};

	private static final Color GREEN = ColorScheme.PROGRESS_COMPLETE_COLOR;
	private static final Color ORANGE = ColorScheme.BRAND_ORANGE;
	private static final Color GREY = new Color(170, 170, 170);
	private static final Color TIER_GOLD = new Color(255, 200, 40);
	/** Empty progress: a mid brown-grey, clearly apart from both the black gaps and the green fill. */
	private static final Color PIP_EMPTY = new Color(100, 90, 76);
	/** The quest list's own colours. */
	private static final Color QUEST_NOT_STARTED = new Color(255, 0, 0);
	private static final Color QUEST_IN_PROGRESS = new Color(255, 255, 0);
	private static final Color QUEST_DONE = new Color(0, 255, 0);

	private final FiveActivePlugin plugin;
	private final FiveActiveConfig config;
	private final SkillIconManager skillIconManager;
	private final SpriteManager spriteManager;
	private final BackgroundComponent background = new BackgroundComponent();
	private final BufferedImage logo = NavIcon.title(1);
	private final Map<Skill, BufferedImage> skillIcons = new EnumMap<>(Skill.class);
	private final Map<Integer, BufferedImage> bossIcons = new HashMap<>();
	private final Map<Skill, BufferedImage> bigSkillIcons = new EnumMap<>(Skill.class);
	private final Map<Integer, BufferedImage> bigBossIcons = new HashMap<>();
	private BufferedImage questIcon;
	/** The boss tier waiting to be unlocked this frame, or -1. */
	private int pendingTier = -1;
	/** Compact cells drawn this frame and what hovering each one says. */
	private final Map<Rectangle, String> cellTips = new java.util.LinkedHashMap<>();

	@Inject
	private Client client;
	@Inject
	private TooltipManager tooltipManager;

	@Inject
	FiveActiveOverlay(FiveActivePlugin plugin, FiveActiveConfig config, SkillIconManager skillIconManager, SpriteManager spriteManager)
	{
		this.plugin = plugin;
		this.config = config;
		this.skillIconManager = skillIconManager;
		this.spriteManager = spriteManager;
		setPosition(OverlayPosition.BOTTOM_RIGHT);
		setPriority(PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		PanelData data = plugin.getOverlayData();
		FiveActiveConfig.OverlayMode mode = config.overlayMode();
		if (data == null || !data.isLoggedIn() || mode == FiveActiveConfig.OverlayMode.OFF
			|| (mode == FiveActiveConfig.OverlayMode.PANEL_CLOSED && plugin.isPanelOpen()))
		{
			return null;
		}

		// Only the sections picked in the settings, in the panel's order
		List<Category> sections = new ArrayList<>();
		if (config.overlayQuests())
		{
			sections.add(Category.QUESTS);
		}
		if (config.overlaySkills())
		{
			sections.add(Category.SKILLS);
		}
		if (config.overlayBosses())
		{
			sections.add(Category.BOSSES);
		}
		if (sections.isEmpty())
		{
			return null;
		}

		if (config.overlayStyle() == FiveActiveConfig.OverlayStyle.COMPACT)
		{
			return renderCompact(g, data, sections);
		}

		int height = PAD + logo.getHeight() + 3 + PAD - 2;
		for (Category category : sections)
		{
			height += sectionHeight(slots(data, category));
		}
		height += SECTION_GAP * (sections.size() - 1);

		background.setRectangle(new Rectangle(0, 0, WIDTH, height));
		background.render(g);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);

		int y = PAD;
		g.drawImage(logo, (WIDTH - logo.getWidth()) / 2, y, null);
		y += logo.getHeight() + 3;

		FiveActivePlugin.OverlayReveal reveal = plugin.getOverlayReveal();
		pendingTier = data.getPendingTier();
		for (int i = 0; i < sections.size(); i++)
		{
			Category category = sections.get(i);
			y = drawSection(g, y + (i == 0 ? 0 : SECTION_GAP), category, slots(data, category), canRoll(data, category), reveal);
		}
		return new Dimension(WIDTH, height);
	}

	// ---------------------------------------------------------------- Compact style

	/**
	 * The logo, then one row of five icon cells per section: skill and boss icons, and the quest tab's icon for
	 * quests. Under each cell a bar shows progress: five segments filling green for skills and bosses (one for
	 * one-kill bosses), and for quests one bar in the quest list's colour. Finished cells get a green tick.
	 * Hovering a cell shows its name.
	 */
	private Dimension renderCompact(Graphics2D g, PanelData data, List<Category> sections)
	{
		int height = PAD + logo.getHeight() + 4 + sections.size() * CELL_BLOCK + (sections.size() - 1) * SECTION_GAP + PAD;
		background.setRectangle(new Rectangle(0, 0, COMPACT_WIDTH, height));
		background.render(g);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);

		int y = PAD;
		g.drawImage(logo, (COMPACT_WIDTH - logo.getWidth()) / 2, y, null);
		y += logo.getHeight() + 4;

		cellTips.clear();
		FiveActivePlugin.OverlayReveal reveal = plugin.getOverlayReveal();
		long now = System.currentTimeMillis();
		for (Category category : sections)
		{
			List<PanelData.SlotView> slots = slots(data, category);
			for (int i = 0; i < Rules.SLOTS; i++)
			{
				int x = PAD + i * (CELL + CELL_GAP);
				if (i >= slots.size())
				{
					// Empty slot (not rolled, or fewer than five available)
					drawEmptyCell(g, x, y);
					continue;
				}
				long revealed = reveal == null ? -1 : reveal.revealTime(category, i);
				PanelData.SlotView slot = slots.get(i);
				if (revealed == 0)
				{
					drawMysteryCell(g, x, y);
					cellTips.put(new Rectangle(x, y, CELL, CELL_BLOCK), "Rolling...");
					continue;
				}
				float done = plugin.completionPop(category, slot.getName());
				if (revealed > 0 && now - revealed < POP_MS)
				{
					drawPoppingCell(g, x, y, category, slot, (now - revealed) / (float) POP_MS, ORANGE);
				}
				else if (done >= 0f)
				{
					drawPoppingCell(g, x, y, category, slot, done, GREEN);
				}
				else
				{
					drawCell(g, x, y, category, slot);
				}
				cellTips.put(new Rectangle(x, y, CELL, CELL_BLOCK), tip(category, slot));
			}
			y += CELL_BLOCK + SECTION_GAP;
		}
		addHoverTooltip();
		return new Dimension(COMPACT_WIDTH, height);
	}

	private void drawCell(Graphics2D g, int x, int y, Category category, PanelData.SlotView slot)
	{
		g.setColor(CELL_BACK);
		g.fillRect(x, y, CELL, CELL);
		BufferedImage icon = category == Category.QUESTS ? questIcon()
			: category == Category.SKILLS ? bigSkillIcon(slot.getSkill())
			: bigBossIcon(slot.getIconSpriteId());
		if (icon != null)
		{
			g.drawImage(icon, x + (CELL - icon.getWidth()) / 2, y + (CELL - icon.getHeight()) / 2, null);
		}

		int barY = y + CELL + 2;
		// Black edge around the whole bar, then the segments inside it
		g.setColor(Color.BLACK);
		g.fillRect(x, barY, CELL, BAR_HEIGHT);
		if (category == Category.QUESTS)
		{
			g.setColor(questColor(slot));
			g.fillRect(x + 1, barY + 1, CELL - 2, BAR_HEIGHT - 2);
		}
		else
		{
			int goal = Math.max(1, slot.getGoal());
			int inner = CELL - 2;
			for (int i = 0; i < goal; i++)
			{
				// Segments share the width exactly, with a 1px black gap between them
				int sx = x + 1 + i * (inner + 1) / goal;
				int ex = x + 1 + (i + 1) * (inner + 1) / goal - 1;
				g.setColor(i < slot.getProgress() || slot.isDone() ? GREEN : PIP_EMPTY);
				g.fillRect(sx, barY + 1, ex - sx, BAR_HEIGHT - 2);
			}
		}

		if (slot.isDone())
		{
			drawPattern(g, TICK, x + CELL - TICK[0].length(), y, GREEN);
		}
	}

	private void drawEmptyCell(Graphics2D g, int x, int y)
	{
		g.setColor(new Color(0, 0, 0, 40));
		g.fillRect(x, y, CELL, CELL);
		g.setColor(new Color(0, 0, 0, 90));
		g.drawRect(x, y, CELL - 1, CELL - 1);
	}

	private void drawMysteryCell(Graphics2D g, int x, int y)
	{
		g.setColor(CELL_BACK);
		g.fillRect(x, y, CELL, CELL);
		Font font = FontManager.getRunescapeBoldFont();
		g.setFont(font);
		FontMetrics fm = g.getFontMetrics();
		int tx = x + (CELL - fm.stringWidth("?")) / 2;
		int ty = y + (CELL - fm.getHeight()) / 2 + fm.getAscent();
		g.setColor(Color.BLACK);
		g.drawString("?", tx + 1, ty + 1);
		g.setColor(GREY);
		g.drawString("?", tx, ty);
		g.setColor(Color.BLACK);
		g.fillRect(x, y + CELL + 2, CELL, BAR_HEIGHT);
	}

	/** A cell that just landed: an orange box springs open past full size and fades, revealing the cell. */
	private void drawPoppingCell(Graphics2D g, int x, int y, Category category, PanelData.SlotView slot, float t, Color color)
	{
		float u = t - 1f;
		float spring = 1f + 2.70158f * u * u * u + 1.70158f * u * u; // easeOutBack
		float scale = 0.5f + 0.5f * spring;
		int w = Math.round((CELL + 4) * scale);
		int h = Math.round((CELL_BLOCK + 4) * scale);
		int bx = x + CELL / 2 - w / 2;
		int by = y + CELL_BLOCK / 2 - h / 2;
		Graphics2D box = (Graphics2D) g.create();
		box.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), Math.round(190 * (1f - t))));
		box.fillRect(bx, by, w, h);
		box.clipRect(bx, by, w, h);
		drawCell(box, x, y, category, slot);
		box.dispose();
	}

	private static String tip(Category category, PanelData.SlotView slot)
	{
		// Tooltips take the game's <col=rrggbb> colour tags
		if (category == Category.QUESTS)
		{
			String state = slot.isDone() || slot.getQuestState() == QuestState.FINISHED ? "Complete"
				: slot.getQuestState() == QuestState.IN_PROGRESS ? "In progress"
				: "Not started";
			return slot.getName() + "</br>" + ColorUtil.wrapWithColorTag(state, questColor(slot));
		}
		return slot.getName() + "</br>" + (slot.isDone()
			? ColorUtil.wrapWithColorTag("Done!", GREEN)
			: slot.getProgress() + "/" + slot.getGoal());
	}

	/** Shows the name of the compact cell under the mouse. */
	private void addHoverTooltip()
	{
		if (client == null || tooltipManager == null)
		{
			return;
		}
		Point mouse = client.getMouseCanvasPosition();
		Rectangle bounds = getBounds();
		if (mouse == null || bounds == null)
		{
			return;
		}
		int mx = mouse.getX() - bounds.x;
		int my = mouse.getY() - bounds.y;
		for (Map.Entry<Rectangle, String> cell : cellTips.entrySet())
		{
			if (cell.getKey().contains(mx, my))
			{
				tooltipManager.add(new Tooltip(cell.getValue()));
				return;
			}
		}
	}

	private static Color questColor(PanelData.SlotView slot)
	{
		return slot.isDone() || slot.getQuestState() == QuestState.FINISHED ? QUEST_DONE
			: slot.getQuestState() == QuestState.IN_PROGRESS ? QUEST_IN_PROGRESS
			: QUEST_NOT_STARTED;
	}

	private static void drawPattern(Graphics2D g, String[] pattern, int x, int y, Color color)
	{
		for (int row = 0; row < pattern.length; row++)
		{
			for (int col = 0; col < pattern[row].length(); col++)
			{
				char ch = pattern[row].charAt(col);
				if (ch == 'o' || ch == 'k')
				{
					g.setColor(ch == 'o' ? color : Color.BLACK);
					g.fillRect(x + col, y + row, 1, 1);
				}
			}
		}
	}

	private BufferedImage bigSkillIcon(Skill skill)
	{
		return skill == null ? null : bigSkillIcons.computeIfAbsent(skill, s -> fit(skillIconManager.getSkillImage(s, false)));
	}

	private BufferedImage bigBossIcon(int spriteId)
	{
		if (spriteId < 0)
		{
			return null;
		}
		BufferedImage cached = bigBossIcons.get(spriteId);
		if (cached == null)
		{
			BufferedImage sprite = spriteManager.getSprite(spriteId, 0);
			if (sprite == null)
			{
				return null;
			}
			cached = fit(sprite);
			bigBossIcons.put(spriteId, cached);
		}
		return cached;
	}

	private BufferedImage questIcon()
	{
		if (questIcon == null)
		{
			BufferedImage sprite = spriteManager.getSprite(SpriteID.SideIcons.QUEST, 0);
			questIcon = sprite == null ? null : fit(sprite);
		}
		return questIcon;
	}

	/** Native size (crisp pixel art), only shrunk if it's bigger than a cell. */
	private static BufferedImage fit(BufferedImage image)
	{
		if (image.getWidth() > CELL - 2 || image.getHeight() > CELL - 2)
		{
			return ImageUtil.resizeImage(image, CELL - 2, CELL - 2, true);
		}
		return image;
	}

	private static List<PanelData.SlotView> slots(PanelData data, Category category)
	{
		return category == Category.QUESTS ? data.getQuests() : category == Category.SKILLS ? data.getSkills() : data.getBosses();
	}

	private static int canRoll(PanelData data, Category category)
	{
		return category == Category.QUESTS ? data.getQuestsCanRoll()
			: category == Category.SKILLS ? data.getSkillsCanRoll()
			: data.getBossesCanRoll();
	}

	/** A header plus one row per slot (a single "none" row when nothing's rolled). */
	private static int sectionHeight(List<PanelData.SlotView> slots)
	{
		return ROW_HEIGHT + ROW_HEIGHT * Math.max(1, slots.size());
	}

	private int drawSection(Graphics2D g, int y, Category category, List<PanelData.SlotView> slots, int canRoll,
		FiveActivePlugin.OverlayReveal reveal)
	{
		// Header: title on the left, "N ready" on the right when there's something to roll
		Font bold = FontManager.getRunescapeBoldFont();
		text(g, category.getTitle(), PAD, y, bold, ORANGE);
		if (reveal != null && reveal.isSpinning(category))
		{
			rightText(g, "Rolling...", y, FontManager.getRunescapeSmallFont(), GREY);
		}
		else if (category == Category.BOSSES && pendingTier >= 0)
		{
			rightText(g, "Tier " + (pendingTier + 1) + " ready!", y, FontManager.getRunescapeSmallFont(), TIER_GOLD);
		}
		else if (canRoll > 0)
		{
			rightText(g, canRoll + " ready to roll", y, FontManager.getRunescapeSmallFont(), GREEN);
		}
		y += ROW_HEIGHT;

		if (slots.isEmpty())
		{
			text(g, "None rolled yet", PAD + 2, y, FontManager.getRunescapeFont(), GREY);
			return y + ROW_HEIGHT;
		}
		long now = System.currentTimeMillis();
		for (int i = 0; i < slots.size(); i++)
		{
			long revealed = reveal == null ? -1 : reveal.revealTime(category, i);
			if (revealed == 0)
			{
				// Its reel is still spinning in the panel: keep the result hidden until it lands
				drawMystery(g, y, category);
			}
			else if (revealed > 0 && now - revealed < POP_MS)
			{
				drawPopping(g, y, category, slots.get(i), (now - revealed) / (float) POP_MS, ORANGE);
			}
			else if (plugin.completionPop(category, slots.get(i).getName()) >= 0f)
			{
				drawPopping(g, y, category, slots.get(i), plugin.completionPop(category, slots.get(i).getName()), GREEN);
			}
			else
			{
				drawRow(g, y, category, slots.get(i));
			}
			y += ROW_HEIGHT;
		}
		return y;
	}

	private void drawRow(Graphics2D g, int y, Category category, PanelData.SlotView slot)
	{
		if (category == Category.QUESTS)
		{
			drawQuest(g, y, slot);
		}
		else
		{
			drawProgressRow(g, y, slot, category == Category.SKILLS ? skillIcon(slot.getSkill()) : bossIcon(slot.getIconSpriteId()));
		}
	}

	/** A slot still being rolled: "???" where its name will be. */
	private void drawMystery(Graphics2D g, int y, Category category)
	{
		text(g, "???", category == Category.QUESTS ? PAD + 2 : PAD + ICON + 4, y, FontManager.getRunescapeFont(), GREY);
	}

	/**
	 * A row that just landed, popping in like the panel's cards: an orange box springs open past full size and
	 * settles, fading as it goes, with the row revealed inside it at its real size (so the text stays sharp).
	 */
	private void drawPopping(Graphics2D g, int y, Category category, PanelData.SlotView slot, float t, Color color)
	{
		float u = t - 1f;
		float spring = 1f + 2.70158f * u * u * u + 1.70158f * u * u; // easeOutBack
		float scale = 0.6f + 0.4f * spring;
		int fullW = WIDTH - 2 * PAD + 4;
		int w = Math.round(fullW * scale);
		int h = Math.round(ROW_HEIGHT * scale);
		int x = (WIDTH - w) / 2;
		int top = y + (ROW_HEIGHT - h) / 2;

		Graphics2D box = (Graphics2D) g.create();
		box.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), Math.round(170 * (1f - t))));
		box.fillRect(x, top, w, h);
		box.clipRect(x, top, w, h);
		drawRow(box, y, category, slot);
		box.dispose();
	}

	/** [icon] name ........ progress squares. Finished rows go green. */
	private void drawProgressRow(Graphics2D g, int y, PanelData.SlotView slot, BufferedImage icon)
	{
		int x = PAD;
		if (icon != null)
		{
			g.drawImage(icon, x + (ICON - icon.getWidth()) / 2, y + (ROW_HEIGHT - icon.getHeight()) / 2, null);
		}
		x += ICON + 4;

		int pipsWidth = slot.getGoal() * PIP + (slot.getGoal() - 1) * PIP_GAP;
		int pipsX = WIDTH - PAD - pipsWidth;
		Font font = FontManager.getRunescapeFont();
		text(g, fit(g, slot.getName(), font, pipsX - 4 - x), x, y, font, slot.isDone() ? GREEN : Color.WHITE);

		int pipY = y + (ROW_HEIGHT - PIP) / 2;
		for (int i = 0; i < slot.getGoal(); i++)
		{
			int px = pipsX + i * (PIP + PIP_GAP);
			g.setColor(Color.BLACK);
			g.fillRect(px - 1, pipY - 1, PIP + 2, PIP + 2);
			g.setColor(i < slot.getProgress() || slot.isDone() ? GREEN : PIP_EMPTY);
			g.fillRect(px, pipY, PIP, PIP);
		}
	}

	/** The quest's name in its quest list colour. */
	private void drawQuest(Graphics2D g, int y, PanelData.SlotView slot)
	{
		Color color = questColor(slot);
		Font font = FontManager.getRunescapeFont();
		text(g, fit(g, slot.getName(), font, WIDTH - 2 * PAD - 2), PAD + 2, y, font, color);
	}

	/** Text with the game's drop shadow, vertically centred in a row starting at y. */
	private static void text(Graphics2D g, String text, int x, int y, Font font, Color color)
	{
		g.setFont(font);
		FontMetrics fm = g.getFontMetrics();
		int baseline = y + (ROW_HEIGHT - fm.getHeight()) / 2 + fm.getAscent();
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, baseline + 1);
		g.setColor(color);
		g.drawString(text, x, baseline);
	}

	private static void rightText(Graphics2D g, String text, int y, Font font, Color color)
	{
		g.setFont(font);
		text(g, text, WIDTH - PAD - g.getFontMetrics().stringWidth(text), y, font, color);
	}

	/** The text, cut short with "..." if it's wider than maxWidth. */
	private static String fit(Graphics2D g, String text, Font font, int maxWidth)
	{
		FontMetrics fm = g.getFontMetrics(font);
		if (fm.stringWidth(text) <= maxWidth)
		{
			return text;
		}
		String cut = text;
		while (cut.length() > 1 && fm.stringWidth(cut + "...") > maxWidth)
		{
			cut = cut.substring(0, cut.length() - 1);
		}
		return cut.trim() + "...";
	}

	private BufferedImage skillIcon(Skill skill)
	{
		return skill == null ? null : skillIcons.computeIfAbsent(skill, s -> skillIconManager.getSkillImage(s, true));
	}

	/** The boss's hiscores icon shrunk to the row, or null until the sprite is available. */
	private BufferedImage bossIcon(int spriteId)
	{
		if (spriteId < 0)
		{
			return null;
		}
		BufferedImage cached = bossIcons.get(spriteId);
		if (cached != null)
		{
			return cached;
		}
		// Overlays render on the client thread, where sprites can be read directly
		BufferedImage sprite = spriteManager.getSprite(spriteId, 0);
		if (sprite == null)
		{
			return null;
		}
		BufferedImage icon = ImageUtil.resizeImage(sprite, ICON, ICON, true);
		bossIcons.put(spriteId, icon);
		return icon;
	}
}

