		.put("dm", "Dream Mentor")
		.put("ham", "Another Slice of H.A.M.")
		.build();

	/** What a lookup found: the one match, or the possibilities (several), or neither (no match). */
	@Value
	static class Result<T>
	{
		T match;
		List<String> options;
		/** More matched than are listed in options. */
		int more;

		static <T> Result<T> of(T match)
		{
			return new Result<>(match, Collections.emptyList(), 0);
		}

		static <T> Result<T> none()
		{
			return new Result<>(null, Collections.emptyList(), 0);
		}
	}

	static Result<Skill> skill(String typed)
	{
		return exact(typed, SKILL_SHORTHAND, Skill.values(), Skill::getName);
	}

	static Result<Boss> boss(String typed)
	{
		return exact(typed, BOSS_SHORTHAND, Boss.values(), Boss::getDisplayName);
	}

	static Result<Quest> quest(String typed)
	{
		String shorthand = QUEST_SHORTHAND.get(clean(typed));
		if (shorthand != null)
		{
			typed = shorthand;
		}
		String wanted = questKey(typed);
		if (wanted.isEmpty())
		{
			return Result.none();
		}
		List<Quest> starts = new ArrayList<>();
		for (Quest quest : Quest.values())
		{
			String key = questKey(quest.getName());
			if (key.equals(wanted))
			{
				return Result.of(quest);
			}
			if (key.startsWith(wanted))
			{
				starts.add(quest);
			}
		}
		if (starts.size() == 1)
		{
			return Result.of(starts.get(0));
		}
		List<String> names = new ArrayList<>();
		for (int i = 0; i < Math.min(MAX_LISTED, starts.size()); i++)
		{
			names.add(starts.get(i).getName());
		}
		return new Result<>(null, names, Math.max(0, starts.size() - MAX_LISTED));
	}

	/** Skills and bosses: shorthand, or the exact name in any case. */
	private static <T> Result<T> exact(String typed, Map<String, String> shorthand, T[] all, Function<T, String> name)
	{
		String wanted = clean(typed);
		String full = shorthand.getOrDefault(wanted, wanted);
		for (T value : all)
		{
			if (name.apply(value).equalsIgnoreCase(full))
			{
				return Result.of(value);
			}
		}
		return Result.none();
	}

	/** Lower case, single spaces, trimmed. */
	private static String clean(String typed)
	{
		return typed == null ? "" : typed.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
	}

	/**
	 * A quest name without case or punctuation, so "cooks assistant" is "Cook's Assistant". "&" counts as "and",
	 * and numbers 1 to 3 as I to III ("dragon slayer 2" is "Dragon Slayer II").
	 */
	static String questKey(String name)
	{
		String words = clean(name).replace("&", " and ")
			.replaceAll("\\b1\\b", "i").replaceAll("\\b2\\b", "ii").replaceAll("\\b3\\b", "iii");
		return words.replaceAll("[^a-z0-9]", "");
	}

	private NameLookup()
	{
	}
}

package com.bswmagicgaming.fiveactive;

import java.awt.Color;
import java.awt.image.BufferedImage;

/**
 * The 16x16 sidebar icon: "5A" in the plugin's pixel font (see {@link PixelFont}), an orange 5 and a white A,
 * each with a one-pixel drop shadow. The panel title uses the same letters and colours.
 */
final class NavIcon
{
	static final Color ORANGE = new Color(255, 152, 0);
	static final Color ORANGE_SHADOW = new Color(150, 80, 0);
	static final Color WHITE = new Color(235, 235, 235);
	static final Color WHITE_SHADOW = new Color(90, 90, 90);

	static BufferedImage create()
	{
		BufferedImage icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		PixelFont.draw(icon, 1, 3, 1,
			new PixelFont.Run("5", ORANGE, ORANGE_SHADOW),
			new PixelFont.Run("A", WHITE, WHITE_SHADOW));
		return icon;
	}

	/** "FIVE ACTIVE" in the same style, scaled up for the panel header. */
	static BufferedImage title(int scale)
	{
		return outline(PixelFont.render(scale,
			new PixelFont.Run("FIVE ", ORANGE, ORANGE_SHADOW),
			new PixelFont.Run("ACTIVE", WHITE, WHITE_SHADOW)));
	}

	/**
	 * Adds a 1px black outline around every drawn pixel (letters and shadow together), like the panel's other
	 * titles, so the logo reads clearly. The image grows by 1px on each side.
	 */
	static BufferedImage outline(BufferedImage image)
	{
		int w = image.getWidth();
		int h = image.getHeight();
		BufferedImage out = new BufferedImage(w + 2, h + 2, BufferedImage.TYPE_INT_ARGB);
		int black = Color.BLACK.getRGB();
		for (int y = 0; y < h; y++)
		{
			for (int x = 0; x < w; x++)
			{
				if ((image.getRGB(x, y) >>> 24) == 0)
				{
					continue;
				}
				// Paint black around the pixel; the real pixels are drawn over it afterwards
				for (int dy = 0; dy <= 2; dy++)
				{
					for (int dx = 0; dx <= 2; dx++)
					{
						out.setRGB(x + dx, y + dy, black);
					}
				}
			}
		}
		for (int y = 0; y < h; y++)
		{
			for (int x = 0; x < w; x++)
			{
				int rgb = image.getRGB(x, y);
				if ((rgb >>> 24) != 0)
				{
					out.setRGB(x + 1, y + 1, rgb);
				}
			}
		}
		return out;
	}

	private NavIcon()
	{
	}
}

package com.bswmagicgaming.fiveactive;

import java.util.Collections;
import java.util.List;
import java.util.Set;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Value;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;

/**
 * Immutable snapshot of everything the side panel shows. Built on the client thread
 * (quest states need it) and handed to Swing, so the panel never touches game state directly.
 */
@Value
@Builder
class PanelData
{
	static final PanelData LOGGED_OUT = PanelData.builder().loggedIn(false).build();

	boolean loggedIn;

	int shuffles;
	int collectionLogSlots;

	List<SlotView> skills;
	int skillsCanRoll;
	/** Skills at 99: permanently unlocked and never rolled. */
	@Builder.Default
	List<Skill> maxedSkills = Collections.emptyList();
	/** No active skills and nothing left to roll. */
	boolean allSkillsDone;
	List<SlotView> bosses;
	int bossesCanRoll;
	List<SlotView> quests;
	int questsCanRoll;
	/** No active quests and nothing left to roll. */
	boolean allQuestsDone;

	/** Categories where a shuffle would change something (there is at least one new option). */
	@Builder.Default
	Set<Category> shufflable = Collections.emptySet();

	int totalKc;
	/** Lifetime numbers for the share card: quests completed (of all), and total level. */
	int questsCompleted;
	int questsTotal;
	int totalLevel;
	int combatLevel;
	/** The IRONMAN varbit: 0 normal, 1 ironman, 2 ultimate, 3 hardcore, 4 group, 5 hardcore group, 6 unranked group. */
	int accountType;
	/** Tiers claimed so far (at least 1). */
	int unlockedTiers;
	/** Index of the tier whose KC is reached but that hasn't been unlocked yet, or -1. Boss rolls wait for it. */
	@Builder.Default
	int pendingTier = -1;
	FiveActiveConfig.KcMode kcMode;
	List<TierView> tiers;

	@Value
	static class SlotView
	{
		String name;
		/** Only set for skill slots, for the icon. */
		Skill skill;
		int progress;
		int goal;
		boolean done;
		boolean fresh;
		/** Only set for quest slots. */
		QuestState questState;
		/** Sprite id for boss slots' icon, or -1. */
		int iconSpriteId;
	}

	enum BossStatus
	{
		ACTIVE,
		ROLLABLE,
		LOCKED
	}

	@Value
	@AllArgsConstructor
	static class BossView
	{
		String name;
		BossStatus status;
		/** Why it's locked (null unless LOCKED). */
		String reason;
		/** Hiscores sprite for the icon, or -1. */
		int iconSpriteId;
		/** Quests and Slayer level the boss needs, each marked met or not (empty if it needs neither). */
		List<Requirement> requirements;

		BossView(String name, BossStatus status, String reason, int iconSpriteId)
		{
			this(name, status, reason, iconSpriteId, Collections.emptyList());
		}
	}

	@Value
	static class Requirement
	{
		String text;
		boolean met;
	}

	@Value
	static class TierView
	{
		int killsRequired;
		boolean unlocked;
		List<BossView> bosses;
	}
}

