package com.bswmagicgaming.fiveactive;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.TreeMap;
import java.util.function.Supplier;
import javax.swing.JComponent;
import javax.swing.Timer;
import lombok.Getter;
import lombok.Value;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Slot machine reveal for freshly rolled slots. Each new slot becomes a reel that scrolls through
 * random candidates, slows down, and lands on the real result one reel after another, then flashes.
 *
 * The result is already decided and saved before this starts; this is purely presentation.
 * Runs on the Swing thread.
 */
class RollAnimation
{
	/** How long the first reel spins before landing. */
	private static final int SPIN_MS = 2400;
	/** Extra spin time for each following reel, so they land one after another. */
	private static final int STAGGER_MS = 800;
	/** How long a landed reel flashes. */
	private static final int FLASH_MS = 800;
	/** After the flash, how long the reel takes to fade into the normal row. */
	private static final int SETTLE_MS = 450;
	/** How long the "NEW!" pop takes to settle. */
	private static final int POP_MS = 250;
	/** Time between candidate changes: starts fast, eases out to slow. */
	private static final int FASTEST_CHANGE_MS = 45;
	private static final int SLOWEST_CHANGE_MS = 380;
	/** Longest time a candidate takes to slide into place. */
	private static final int MAX_SLIDE_MS = 110;
	/** Minimum gap between tick sounds, so several reels don't turn into noise. */
	private static final int TICK_SOUND_GAP_MS = 70;

	private static final Color ORANGE = ColorScheme.BRAND_ORANGE;
	private static final Item MYSTERY = new Item("", "???", null);

	/**
	 * Something a reel can show: a name and an optional icon. id identifies what it is (e.g. the Skill's name()).
	 * The icon is looked up every frame, so an icon that is still loading appears as soon as it arrives.
	 */
	@Value
	static class Item
	{
		String id;
		String name;
		Supplier<Image> iconSource;

		Image getIcon()
		{
			return iconSource == null ? null : iconSource.get();
		}
	}

	interface Listener
	{
		/** A reel moved to the next candidate. */
		void tick();

		/** A reel landed on its result. */
		void land(Item result);

		/** Every reel has landed and finished flashing. */
		void finished();
	}

	@Getter
	private final Category category;
	private final Map<Integer, Reel> reels = new TreeMap<>();
	private final List<Item> candidates;
	private final Listener listener;
	private final Random random = new Random();
	private final Timer timer;
	/** Row components currently on screen; the panel re-registers them whenever it rebuilds. */
	private final List<JComponent> rows = new ArrayList<>();
	private long lastTickSound;
	private boolean finished;

	/**
	 * @param results slot index to the item it will land on, in top-to-bottom order
	 * @param candidates items to flash past while spinning
	 */
	RollAnimation(Category category, Map<Integer, Item> results, List<Item> candidates, Listener listener)
	{
		this.category = category;
		this.candidates = candidates;
		this.listener = listener;

		long now = System.currentTimeMillis();
		int order = 0;
		for (Map.Entry<Integer, Item> result : new TreeMap<>(results).entrySet())
		{
			Reel reel = new Reel(result.getValue(), now, now + SPIN_MS + (long) order * STAGGER_MS);
			reel.current = randomCandidate(null, reel.target);
			reels.put(result.getKey(), reel);
			order++;
		}
		timer = new Timer(16, e -> step());
	}

	void start()
	{
		timer.start();
	}

	/** Stops immediately without a reveal (e.g. the plugin shut down). */
	void cancel()
	{
		timer.stop();
		finished = true;
	}

	boolean isAnimating(int slotIndex)
	{
		return !finished && reels.containsKey(slotIndex);
	}

	/** Called by the panel at the start of every rebuild, before it creates new rows. */
	void clearRows()
	{
		rows.clear();
	}

	/**
	 * A row that draws the reel for slot index. finalRow is the normal row it will be replaced by: the reel
	 * takes its size, and fades into a picture of it at the end so the swap is seamless.
	 */
	JComponent createRow(int slotIndex, JComponent finalRow)
	{
		ReelRow row = new ReelRow(reels.get(slotIndex), finalRow);
		rows.add(row);
		return row;
	}

	private void step()
	{
		long now = System.currentTimeMillis();
		boolean ticked = false;
		long lastLanding = 0;
		boolean allLanded = true;

		for (Reel reel : reels.values())
		{
			if (!reel.landed)
			{
				if (now >= reel.stopAt)
				{
					reel.show(reel.target, now, MAX_SLIDE_MS + 40);
					reel.landed = true;
					reel.landedAt = now;
					listener.land(reel.target);
				}
				else if (now >= reel.nextChangeAt)
				{
					double progress = (double) (now - reel.startAt) / (reel.stopAt - reel.startAt);
					long interval = FASTEST_CHANGE_MS + Math.round((SLOWEST_CHANGE_MS - FASTEST_CHANGE_MS) * Math.pow(progress, 2.5));
					reel.show(randomCandidate(reel.current, reel.target), now, Math.min(interval, MAX_SLIDE_MS));
					reel.nextChangeAt = now + interval;
					ticked = true;
				}
			}
			allLanded &= reel.landed;
			lastLanding = Math.max(lastLanding, reel.landedAt);
		}

		if (ticked && now - lastTickSound >= TICK_SOUND_GAP_MS)
		{
			lastTickSound = now;
			listener.tick();
		}

		rows.forEach(JComponent::repaint);

		if (allLanded && now - lastLanding >= FLASH_MS + SETTLE_MS)
		{
			timer.stop();
			finished = true;
			listener.finished();
		}
	}

	/**
	 * A random candidate that isn't what's showing now, isn't this reel's result (so the landing is a surprise),
	 * and hasn't already landed on another reel (each result can only appear once).
	 */
	private Item randomCandidate(Item current, Item target)
	{
		List<Item> options = new ArrayList<>();
		for (Item item : candidates)
		{
			String name = item.getName();
			boolean landedElsewhere = reels.values().stream().anyMatch(r -> r.landed && r.target.getName().equals(name));
			if (!name.equals(target.getName())
				&& (current == null || !name.equals(current.getName()))
				&& !landedElsewhere)
			{
				options.add(item);
			}
		}
		// Tiny pool with nothing else to show: spin a mystery card rather than give the result away early
		return options.isEmpty() ? MYSTERY : options.get(random.nextInt(options.size()));
	}

	private static class Reel
	{
		final Item target;
		final long startAt;
		final long stopAt;
		Item previous;
		Item current;
		long changedAt;
		long slideMs = 1;
		long nextChangeAt;
		boolean landed;
		long landedAt;

		Reel(Item target, long startAt, long stopAt)
		{
			this.target = target;
			this.startAt = startAt;
			this.stopAt = stopAt;
			this.changedAt = startAt;
			this.nextChangeAt = startAt;
		}

		void show(Item item, long now, long slide)
		{
			previous = current;
			current = item;
			changedAt = now;
			slideMs = Math.max(1, slide);
		}
	}

	/** Custom-painted row: the reel window, the flash when it lands, and the "NEW!" pop. */
	private static class ReelRow extends JComponent
	{
		private static final int PAD_X = 6;
		private static final int ICON_SIZE = FiveActivePanel.ICON_SIZE;
		private static final int ICON_GAP = 6;
		/** Space kept free on the right for the "NEW!" pop. */
		private static final int NEW_RESERVE = 44;

		private final Reel reel;
		private final JComponent finalRow;
		private BufferedImage finalImage;
		/** The normal row's contents without its background, for drawing the landed result. */
		private BufferedImage contentImage;

		ReelRow(Reel reel, JComponent finalRow)
		{
			this.reel = reel;
			this.finalRow = finalRow;
			int height = finalRow.getPreferredSize().height;
			setPreferredSize(new Dimension(0, height));
			setMinimumSize(new Dimension(0, height));
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			int w = getWidth();
			int h = getHeight();
			long now = System.currentTimeMillis();

			g2.setColor(ColorScheme.DARK_GRAY_COLOR);
			g2.fillRect(0, 0, w, h);

			float flash = reel.landed ? 1f - clamp((now - reel.landedAt) / (float) FLASH_MS) : 0f;
			if (flash > 0)
			{
				g2.setColor(withAlpha(ORANGE, (int) (150 * flash)));
				g2.fillRect(0, 0, w, h);
			}

			// Reel window: the previous item slides up and out while the current one slides in from below
			float slide = clamp((now - reel.changedAt) / (float) reel.slideMs);
			slide = 1f - (1f - slide) * (1f - slide); // ease out
			// Clip the scrolling items to the row; remember the original clip so it can be restored exactly
			// (setClip(null) would remove all clipping and let later drawing spill outside the row)
			Shape rowClip = g2.getClip();
			g2.clipRect(1, 1, w - 2, h - 2);
			if (reel.previous != null && slide < 1f)
			{
				drawItem(g2, reel.previous, (int) (-slide * h), w, h, reel.landed ? 0.5f : 1f);
			}
			drawItem(g2, reel.current, (int) ((1f - slide) * h), w, h, 1f);
			g2.setClip(rowClip);

			if (reel.landed)
			{
				drawNewPop(g2, now, w, h);
			}
			else
			{
				// Fade the top and bottom edges so it reads as a spinning drum
				g2.setPaint(new GradientPaint(0, 0, ColorScheme.DARK_GRAY_COLOR, 0, h / 3f, withAlpha(ColorScheme.DARK_GRAY_COLOR, 0)));
				g2.fillRect(0, 0, w, h / 3);
				g2.setPaint(new GradientPaint(0, h * 2 / 3f, withAlpha(ColorScheme.DARK_GRAY_COLOR, 0), 0, h, ColorScheme.DARK_GRAY_COLOR));
				g2.fillRect(0, h * 2 / 3, w, h - h * 2 / 3);
			}

			// Border: steady orange while spinning, bright flash when landed
			float border = reel.landed ? flash : 0.8f;
			if (border > 0)
			{
				g2.setColor(withAlpha(ORANGE, (int) (255 * border)));
				g2.setStroke(new BasicStroke(reel.landed ? 2f : 1f));
				g2.drawRect(0, 0, w - 1, h - 1);
			}

			// Settle: cross-fade into a picture of the normal row, which then takes this row's place
			float settle = reel.landed ? clamp((now - reel.landedAt - FLASH_MS) / (float) SETTLE_MS) : 0f;
			if (settle > 0)
			{
				float eased = settle * settle * (3f - 2f * settle); // smoothstep
				g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, eased));
				g2.drawImage(finalImage(w, h), 0, 0, null);
			}
			g2.dispose();
		}

		/** The normal row rendered off-screen at this size (cached). */
		private BufferedImage finalImage(int w, int h)
		{
			if (finalImage == null || finalImage.getWidth() != w || finalImage.getHeight() != h)
			{
				finalImage = render(w, h);
			}
			return finalImage;
		}

		/** The normal row's contents (icon, name, status) without its background, at this size (cached). */
		private BufferedImage contentImage(int w, int h)
		{
			if (contentImage == null || contentImage.getWidth() != w || contentImage.getHeight() != h)
			{
				boolean opaque = finalRow.isOpaque();
				finalRow.setOpaque(false);
				try
				{
					contentImage = render(w, h);
				}
				finally
				{
					finalRow.setOpaque(opaque);
				}
			}
			return contentImage;
		}

		private BufferedImage render(int w, int h)
		{
			finalRow.setSize(w, h);
			layoutTree(finalRow);
			BufferedImage image = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
			Graphics2D g = image.createGraphics();
			finalRow.printAll(g);
			g.dispose();
			return image;
		}

		private static void layoutTree(Component component)
		{
			component.doLayout();
			if (component instanceof Container)
			{
				for (Component child : ((Container) component).getComponents())
				{
					layoutTree(child);
				}
			}
		}

		/** Icon and name, the name wrapped onto as many lines as the row fits (long quest names), centred vertically. */
		private void drawItem(Graphics2D g2, Item item, int offsetY, int w, int h, float alpha)
		{
			if (item == null)
			{
				return;
			}
			Graphics2D g = (Graphics2D) g2.create();
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
			if (item == reel.target)
			{
				// The result is the real row itself (same icon spot, name layout and status line), so when the row
				// takes over at the end nothing moves. Its NEW! is left out; the pop draws that.
				g.clipRect(0, offsetY, w - NEW_RESERVE, h);
				g.drawImage(contentImage(w, h), 0, offsetY, null);
				g.dispose();
				return;
			}
			int x = PAD_X;
			Image icon = item.getIcon();
			if (icon != null)
			{
				g.drawImage(icon, x, offsetY + (h - ICON_SIZE) / 2, ICON_SIZE, ICON_SIZE, null);
				x += ICON_SIZE + ICON_GAP;
			}
			Font font = FontManager.getRunescapeFont();
			g.setFont(font);
			FontMetrics fm = g.getFontMetrics();
			// Keep clear of the right edge, where "NEW!" pops in
			List<String> lines = wrap(item.getName(), fm, w - x - NEW_RESERVE, Math.max(1, (h - 4) / fm.getHeight()));
			int top = offsetY + (h - lines.size() * fm.getHeight()) / 2;
			g.setColor(Color.WHITE);
			for (int i = 0; i < lines.size(); i++)
			{
				g.drawString(lines.get(i), x, top + i * fm.getHeight() + fm.getAscent());
			}
			g.dispose();
		}

		/** Greedy word wrap to maxWidth, at most maxLines lines (the last one ends in "..." if cut short). */
		private static List<String> wrap(String text, FontMetrics fm, int maxWidth, int maxLines)
		{
			List<String> lines = new ArrayList<>();
			StringBuilder line = new StringBuilder();
			for (String word : text.split(" "))
			{
				String attempt = line.length() == 0 ? word : line + " " + word;
				if (fm.stringWidth(attempt) <= maxWidth || line.length() == 0)
				{
					line.setLength(0);
					line.append(attempt);
				}
				else
				{
					lines.add(line.toString());
					line.setLength(0);
					line.append(word);
				}
			}
			lines.add(line.toString());
			if (lines.size() > maxLines)
			{
				List<String> cut = new ArrayList<>(lines.subList(0, maxLines));
				cut.set(maxLines - 1, cut.get(maxLines - 1) + "...");
				return cut;
			}
			return lines;
		}

		/** "NEW!" on the right that pops in large and settles to normal size. */
		private void drawNewPop(Graphics2D g2, long now, int w, int h)
		{
			float t = clamp((now - reel.landedAt) / (float) POP_MS);
			float scale = 1f + 0.8f * (1f - t) * (1f - t);
			Font font = FontManager.getRunescapeBoldFont();
			Graphics2D g = (Graphics2D) g2.create();
			g.setFont(font);
			FontMetrics fm = g.getFontMetrics();
			String text = "NEW!";
			int textW = fm.stringWidth(text);
			// Settles where the row's NEW! sits; while it's popped large, shift left so it stays inside the row
			int cx = Math.min(w - PAD_X - textW / 2, w - 2 - Math.round(textW * scale / 2f));
			int cy = h / 2;
			g.translate(cx, cy);
			g.scale(scale, scale);
			g.setColor(new Color(0, 0, 0, 160));
			g.drawString(text, -textW / 2 + 1, fm.getAscent() / 2 + 1);
			g.setColor(ORANGE); // same orange NEW! as the row it fades into
			g.drawString(text, -textW / 2, fm.getAscent() / 2);
			g.dispose();
		}

		private static float clamp(float value)
		{
			return Math.max(0f, Math.min(1f, value));
		}

		private static Color withAlpha(Color color, int alpha)
		{
			return new Color(color.getRed(), color.getGreen(), color.getBlue(), Math.max(0, Math.min(255, alpha)));
		}
	}
}

package com.bswmagicgaming.fiveactive;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import java.util.function.Predicate;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;

/**
 * Decides what can be rolled and performs the rolls. Must be used on the client thread,
 * because reading quest state runs a client script.
 */
@Singleton
class RollingEngine
{
	private static final int MAX_LEVEL = 99;

	private final Client client;
	private final Random random = new Random();

	@Inject
	RollingEngine(Client client)
	{
		this.client = client;
	}

	/** Reads every quest's state once. Pass the result around instead of calling getState repeatedly. */
	Map<Quest, QuestState> questStates()
	{
		Map<Quest, QuestState> states = new EnumMap<>(Quest.class);
		for (Quest quest : Quest.values())
		{
			states.put(quest, quest.getState(client));
		}
		return states;
	}

	private static boolean finished(Map<Quest, QuestState> states, Quest quest)
	{
		return states.get(quest) == QuestState.FINISHED;
	}

	// ---------------------------------------------------------------- Skills

	boolean isSkillUnlocked(Skill skill, Map<Quest, QuestState> states)
	{
		Quest unlock = Rules.SKILL_UNLOCK_QUESTS.get(skill);
		return unlock == null || finished(states, unlock);
	}

	/** A skill at 99 can't be levelled further, so it is permanently unlocked instead of rollable. */
	boolean isMaxed(Skill skill)
	{
		return client.getRealSkillLevel(skill) >= MAX_LEVEL;
	}

	/** Skills that could be rolled right now (ignoring which are already active). */
	List<Skill> rollableSkills(Map<Quest, QuestState> states)
	{
		List<Skill> skills = new ArrayList<>();
		for (Skill skill : Skill.values())
		{
			if (!Rules.NEVER_ROLLED.contains(skill)
				&& isSkillUnlocked(skill, states)
				&& !isMaxed(skill))
			{
				skills.add(skill);
			}
		}
		return skills;
	}

	/**
	 * Replaces completed skill slots (or every slot when replaceAll), keeping untouched slots in place.
	 * One active skill must always be a combat skill below 99 (maxed skills aren't rollable). Only once every
	 * combat skill is 99 are there none left to require, and all five can be non-combat.
	 * Fills fewer than five slots once there aren't enough rollable skills left.
	 */
	List<Slot<Skill>> rollSkills(List<Slot<Skill>> current, boolean replaceAll, Map<Quest, QuestState> states)
	{
		return replaceAll
			? shuffle(current, rollableSkills(states), Rules.COMBAT_SKILLS::contains)
			: refill(current, false, rollableSkills(states), Rules.COMBAT_SKILLS::contains);
	}

	// ---------------------------------------------------------------- Bosses

	/**
	 * Why a boss can't be rolled right now, or null if it can. Ignores whether it is already active.
	 * unlockedTiers is how many tiers have been claimed; totalKc only decides how a locked tier is described.
	 */
	String bossLockReason(Boss boss, int unlockedTiers, int totalKc, Map<Quest, QuestState> states)
	{
		BossTiers.Tier tier = BossTiers.tierOf(boss);
		if (tier == null)
		{
			return "Not in the boss pool";
		}
		int index = BossTiers.TIERS.indexOf(tier);
		if (index >= unlockedTiers)
		{
			return totalKc >= tier.getKillsRequired()
				? "Unlock Tier " + (index + 1) + " in the Bosses section"
				: "Unlocks at " + tier.getKillsRequired() + " total KC";
		}
		for (Quest quest : boss.getRequiredQuests())
		{
			if (!finished(states, quest))
			{
				return "Needs " + quest.getName();
			}
		}
		if (boss.getSlayerLevel() > 0 && client.getRealSkillLevel(Skill.SLAYER) < boss.getSlayerLevel())
		{
			return "Needs " + boss.getSlayerLevel() + " Slayer";
		}
		return null;
	}

	/** Bosses that could be rolled right now (ignoring which are already active). */
	List<Boss> rollableBosses(int unlockedTiers, Map<Quest, QuestState> states)
	{
		List<Boss> bosses = new ArrayList<>();
		for (BossTiers.Tier tier : BossTiers.TIERS)
		{
			for (Boss boss : tier.getBosses())
			{
				if (bossLockReason(boss, unlockedTiers, 0, states) == null)
				{
					bosses.add(boss);
				}
			}
		}
		return bosses;
	}

	List<Slot<Boss>> rollBosses(List<Slot<Boss>> current, boolean replaceAll, int unlockedTiers, Map<Quest, QuestState> states)
	{
		return replaceAll
			? shuffle(current, rollableBosses(unlockedTiers, states), null)
			: refill(current, false, rollableBosses(unlockedTiers, states), null);
	}

	// ---------------------------------------------------------------- Quests

	boolean isQuestRollable(Quest quest, Map<Quest, QuestState> states)
	{
		// Miniquests are rolled like any other quest
		if (QuestRequirements.NEVER_ROLLED.contains(quest) || finished(states, quest))
		{
			return false;
		}
		for (Quest prereq : QuestRequirements.prerequisites(quest))
		{
			if (!finished(states, prereq))
			{
				return false;
			}
		}
		return true;
	}

	List<Quest> rollableQuests(Map<Quest, QuestState> states)
	{
		List<Quest> quests = new ArrayList<>();
		for (Quest quest : Quest.values())
		{
			if (isQuestRollable(quest, states))
			{
				quests.add(quest);
			}
		}
		return quests;
	}

	List<Slot<Quest>> rollQuests(List<Slot<Quest>> current, boolean replaceAll, Map<Quest, QuestState> states)
	{
		return replaceAll
			? shuffle(current, rollableQuests(states), null)
			: refill(current, false, rollableQuests(states), null);
	}

	// ---------------------------------------------------------------- Shuffles

	boolean canShuffleSkills(List<Slot<Skill>> current, Map<Quest, QuestState> states)
	{
		return canShuffle(current, rollableSkills(states));
	}

	boolean canShuffleBosses(List<Slot<Boss>> current, int unlockedTiers, Map<Quest, QuestState> states)
	{
		return canShuffle(current, rollableBosses(unlockedTiers, states));
	}

	boolean canShuffleQuests(List<Slot<Quest>> current, Map<Quest, QuestState> states)
	{
		return canShuffle(current, rollableQuests(states));
	}

	/** A shuffle is only worth spending if there is at least one option that isn't already in the category. */
	private static <T> boolean canShuffle(List<Slot<T>> current, List<T> eligible)
	{
		Set<T> currentValues = current.stream().map(Slot::getValue).collect(Collectors.toSet());
		return !current.isEmpty() && eligible.stream().anyMatch(v -> !currentValues.contains(v));
	}

	/**
	 * Re-rolls every slot, favouring new outcomes as hard as possible: if there are at least five options
	 * not currently in the category, all five results are new. If there are fewer, every one of them is
	 * included and the remaining slots are filled from the current values.
	 *
	 * @param mustHaveOne if non-null and any eligible value satisfies it, one result must satisfy it
	 * (taken from the new options when possible, otherwise kept from the current values)
	 */
	private <T> List<Slot<T>> shuffle(List<Slot<T>> current, List<T> eligible, Predicate<T> mustHaveOne)
	{
		Set<T> currentValues = current.stream().map(Slot::getValue).collect(Collectors.toSet());
		List<T> fresh = eligible.stream().filter(v -> !currentValues.contains(v)).collect(Collectors.toList());
		List<T> old = eligible.stream().filter(currentValues::contains).collect(Collectors.toList());
		Collections.shuffle(fresh, random);
		Collections.shuffle(old, random);

		List<T> picks = new ArrayList<>();
		if (mustHaveOne != null && eligible.stream().anyMatch(mustHaveOne))
		{
			T required = fresh.stream().filter(mustHaveOne).findFirst()
				.orElseGet(() -> old.stream().filter(mustHaveOne).findFirst().orElse(null));
			picks.add(required);
			fresh.remove(required);
			old.remove(required);
		}
		while (picks.size() < Rules.SLOTS && !fresh.isEmpty())
		{
			picks.add(fresh.remove(0));
		}
		while (picks.size() < Rules.SLOTS && !old.isEmpty())
		{
			picks.add(old.remove(0));
		}
		// Don't always put the required pick in the top slot
		Collections.shuffle(picks, random);
		return picks.stream().map(Slot::of).collect(Collectors.toList());
	}

	// ---------------------------------------------------------------- Shared

	/** How many slots a free roll would fill (completed slots plus empty ones). */
	static int openSlots(List<? extends Slot<?>> slots)
	{
		int done = (int) slots.stream().filter(Slot::isDone).count();
		return done + Math.max(0, Rules.SLOTS - slots.size());
	}

	/**
	 * Fills every open position (completed slots, empty slots, or all slots when replaceAll) with a random
	 * eligible value. Kept slots stay in their position so the panel doesn't jump around. Values that were
	 * just in a slot are avoided when possible so a re-roll always feels like a change.
	 *
	 * @param mustHaveOne if non-null, at least one slot must satisfy this (e.g. a combat skill), when possible
	 */
	private <T> List<Slot<T>> refill(List<Slot<T>> current, boolean replaceAll, List<T> eligible, Predicate<T> mustHaveOne)
	{
		List<Slot<T>> result = new ArrayList<>();
		List<Integer> open = new ArrayList<>();
		for (int i = 0; i < Rules.SLOTS; i++)
		{
			Slot<T> slot = i < current.size() ? current.get(i) : null;
			if (slot == null || slot.isDone() || replaceAll)
			{
				open.add(i);
				result.add(null);
			}
			else
			{
				result.add(slot);
			}
		}

		Set<T> taken = result.stream().filter(s -> s != null).map(Slot::getValue).collect(Collectors.toCollection(HashSet::new));
		Set<T> recent = current.stream().map(Slot::getValue).collect(Collectors.toSet());
		boolean needMandatory = mustHaveOne != null && taken.stream().noneMatch(mustHaveOne);

		for (int index : open)
		{
			List<T> candidates = eligible.stream().filter(v -> !taken.contains(v)).collect(Collectors.toList());
			if (needMandatory)
			{
				List<T> mandatory = candidates.stream().filter(mustHaveOne).collect(Collectors.toList());
				// If nothing eligible satisfies the requirement, fill the slot anyway rather than leave it empty
				if (!mandatory.isEmpty())
				{
					candidates = mandatory;
				}
			}

			T pick = pick(candidates, recent);
			if (pick == null)
			{
				continue;
			}
			result.set(index, Slot.of(pick));
			taken.add(pick);
			needMandatory = false;
		}

		result.removeIf(s -> s == null);
		return result;
	}

	/** Random candidate, preferring ones not in avoid. Null if there are no candidates. */
	private <T> T pick(List<T> candidates, Set<T> avoid)
	{
		List<T> preferred = candidates.stream().filter(v -> !avoid.contains(v)).collect(Collectors.toList());
		List<T> from = preferred.isEmpty() ? candidates : preferred;
		return from.isEmpty() ? null : from.get(random.nextInt(from.size()));
	}
}

package com.bswmagicgaming.fiveactive;

import com.google.common.collect.ImmutableMap;
import com.google.common.collect.ImmutableSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.Skill;

/**
 * Core tuning knobs for the Five Active game mode. Change these to rebalance the mode.
 * Boss tiers and milestones live in {@link BossTiers}; quest prerequisites live in {@link QuestRequirements}.
 */
final class Rules
{
	/** How many skills / bosses / quests are active at once. */
	static final int SLOTS = 5;

	/** Level-ups needed in an active skill before it is completed and can be replaced. */
	static final int LEVELS_TO_COMPLETE_SKILL = 5;

	/** Kills needed on an active boss before it is completed and can be replaced. */
	static final int KILLS_TO_COMPLETE_BOSS = 5;

	/** How long the "NEW" badge shows on a freshly rolled slot. */
	static final int NEW_BADGE_SECONDS = 7;

	/** How long a completed quest or skill with nothing left to replace it stays on show before leaving the list. */
	static final int STRANDED_SLOT_SECONDS = 7;

	/** The highest skill level. */
	static final int MAX_LEVEL = 99;

	/** Level-ups a skill rolled at this level needs in all: 5, up to the next multiple of 5, or 4 from 95 to 99. */
	static int skillGoalFrom(int level)
	{
		int from = level - level % LEVELS_TO_COMPLETE_SKILL;
		return Math.min(from + LEVELS_TO_COMPLETE_SKILL, MAX_LEVEL) - from;
	}

	/** How many of those a skill rolled at this level already has: level 1 is 1/5, level 5 is 0/5, 97 is 2/4. */
	static int skillProgressFrom(int level)
	{
		return level % LEVELS_TO_COMPLETE_SKILL;
	}

	/** Level-ups a skill slot needs to complete: usually 5, fewer for one rolled on the last stretch to 99. */
	static int skillGoal(Slot<?> slot)
	{
		return slot.getGoal() > 0 ? slot.getGoal() : LEVELS_TO_COMPLETE_SKILL;
	}

	/**
	 * The goal shown with a logged level-up, from the level alone: past 95 the slot can only have been rolled on the
	 * last stretch (95 to 99), which is 4 levels; every other slot is 5.
	 */
	static int skillGoalAtLevel(int level)
	{
		return level > MAX_LEVEL - MAX_LEVEL % LEVELS_TO_COMPLETE_SKILL ? MAX_LEVEL % LEVELS_TO_COMPLETE_SKILL : LEVELS_TO_COMPLETE_SKILL;
	}

	/** Collection log slots needed per Shuffle earned. */
	static final int CLOG_SLOTS_PER_SHUFFLE = 50;

	/** At least one active skill must always come from this pool so the player can fight. */
	static final Set<Skill> COMBAT_SKILLS = ImmutableSet.of(
		Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.RANGED, Skill.MAGIC);

	/** Skills that can never be rolled. Hitpoints is always considered active. */
	static final Set<Skill> NEVER_ROLLED = ImmutableSet.of(Skill.HITPOINTS);

	/** Skills that cannot be rolled until the listed quest is complete. */
	static final Map<Skill, Quest> SKILL_UNLOCK_QUESTS = ImmutableMap.of(
		Skill.HERBLORE, Quest.DRUIDIC_RITUAL,
		Skill.RUNECRAFT, Quest.RUNE_MYSTERIES,
		Skill.SAILING, Quest.PANDEMONIUM);

	/** Bank values the History view marks the first time the bank is worth them. */
	static final long[] BANK_MILESTONES = {100_000L, 1_000_000L, 10_000_000L, 100_000_000L, 1_000_000_000L};

	private Rules()
	{
	}
}

