/**
 * The run's history log and its backups, kept as plain files per account in the plugin's data folder
 * (.runelite/plugin-data/five-active/), beside (not in) RuneLite's settings: the log grows all run long,
 * and appending a line to a file is cheaper and safer than rewriting one ever-growing setting.
 * It also means a run survives its settings being lost or reset.
 *
 * <ul>
 * <li>history.jsonl: one {@link HistoryEntry} per line, only ever appended to.</li>
 * <li>backups/: copies of the saved run (not the log) from each login, the newest {@link #MAX_BACKUPS} kept.</li>
 * </ul>
 * A save code is the run and its log together, compressed into one line of text to copy somewhere safe.
 *
 * The files are only ever touched on this class's own background thread, one job at a time and in order, so
 * the game never waits on the disk. The log's entries are kept in memory too, for the panel.
 */
@Slf4j
@Singleton
class RunHistory
{
	private static final String HISTORY_FILE = "history.jsonl";
	private static final String BACKUP_DIR = "backups";
	private static final String SHARE_DIR = "share";
	private static final int MAX_BACKUPS = 30;
	private static final String CODE_PREFIX = "FA1:";
	private static final String FILE_TIME = "yyyy-MM-dd_HH-mm-ss";

	private final Gson gson;
	private final ClientThread clientThread;
	/** The plugin's data folder, set on start up. */
	private Filepath root;
	/** Does the file work, in order. Null while the plugin is off. */
	private ExecutorService disk;
	/** The loaded account's folder, or null when logged out. */
	private volatile Filepath folder;
	/** Bumped on every load and unload, so a slow load for an account that's since gone is dropped. */
	private int generation;
	private final List<HistoryEntry> entries = new CopyOnWriteArrayList<>();

	@Inject
	RunHistory(Gson gson, ClientThread clientThread)
	{
		this.gson = gson;
		this.clientThread = clientThread;
	}

	/** A saved copy of the run. */
	@Value
	static class Backup
	{
		Filepath file;
		long time;
		String stateJson;
	}

	/** A pasted save code, decoded. history is null for a code without one. */
	@Value
	static class SaveCode
	{
		String stateJson;
		List<HistoryEntry> history;
	}

	void start(Filepath root)
	{
		this.root = root;
		disk = Executors.newSingleThreadExecutor(r ->
		{
			Thread thread = new Thread(r, "Five Active files");
			thread.setDaemon(true);
			return thread;
		});
		// So "Open backup folder" has somewhere to open even before any account has logged in
		onDisk(root::createDirectories);
	}

	void stop()
	{
		// Anything still queued (the last few log lines) is written, then the thread ends; nothing waits for it
		if (disk != null)
		{
			disk.shutdown();
			disk = null;
		}
		unload();
	}

	/** Runs file work on the background thread, in order with the rest. */
	private void onDisk(IoTask task)
	{
		ExecutorService executor = disk;
		if (executor == null)
		{
			return;
		}
		executor.execute(() ->
		{
			try
			{
				task.run();
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Five Active: file error", e);
			}
		});
	}

	private interface IoTask
	{
		void run() throws IOException;
	}

	// ---------------------------------------------------------------- Log

	/**
	 * Loads an account's log in the background. Meanwhile it backs up stateJson (the run as it was at login;
	 * may be null) and writes accountName (may be null) beside it so people can tell the folders apart.
	 * onLoaded gets the account's backups, newest first, on the client thread once the log is in.
	 */
	synchronized void load(String profileKey, String accountName, String stateJson, Consumer<List<Backup>> onLoaded)
	{
		if (root == null)
		{
			return;
		}
		Filepath account = root.joinSegment(profileKey.replaceAll("[^A-Za-z0-9._-]", "_"));
		folder = account;
		entries.clear();
		int loading = ++generation;
		onDisk(() ->
		{
			account.createDirectories();
			if (accountName != null)
			{
				account.joinSegment("account.txt").write(accountName);
			}
			List<HistoryEntry> read = read(account.joinSegment(HISTORY_FILE));
			if (stateJson != null)
			{
				writeBackup(account, stateJson);
			}
			List<Backup> backups = readBackups(account);
			clientThread.invoke(() ->
			{
				synchronized (this)
				{
					if (generation != loading)
					{
						return;
					}
					// Anything logged while this was loading goes after what was already there
					entries.addAll(0, read);
				}
				onLoaded.accept(backups);
			});
		});
	}

	synchronized void unload()
	{
		folder = null;
		generation++;
		entries.clear();
	}

	boolean isLoaded()
	{
		return folder != null;
	}

	/** Every entry, oldest first. Safe to read from any thread. */
	List<HistoryEntry> getEntries()
	{
		return Collections.unmodifiableList(entries);
	}

	boolean isEmpty()
	{
		return entries.isEmpty();
	}

	synchronized void add(HistoryEntry entry)
	{
		Filepath account = folder;
		if (account == null)
		{
			return;
		}
		entries.add(entry);
		String line = gson.toJson(entry) + "\n";
		onDisk(() -> account.joinSegment(HISTORY_FILE).write(line, StandardOpenOption.CREATE, StandardOpenOption.APPEND));
	}

	/** Swaps the whole log for another (restoring a save code). The old one is kept beside it, renamed. */
	synchronized void replace(List<HistoryEntry> history)
	{
		Filepath account = folder;
		if (account == null)
		{
			return;
		}
		entries.clear();
		entries.addAll(history);
		StringBuilder lines = new StringBuilder();
		for (HistoryEntry entry : history)
		{
			lines.append(gson.toJson(entry)).append('\n');
		}
		String renamed = "history-replaced-" + stamp(System.currentTimeMillis()) + ".jsonl";
		onDisk(() ->
		{
			Filepath file = account.joinSegment(HISTORY_FILE);
			if (file.exists())
			{
				file.moveTo(account.joinSegment(renamed));
			}
			file.write(lines.toString());
		});
	}

	/** Starts a new, empty log. The old one is kept beside it, renamed. */
	synchronized void archive()
	{
		replace(Collections.emptyList());
	}

	private List<HistoryEntry> read(Filepath file) throws IOException
	{
		List<HistoryEntry> read = new ArrayList<>();
		if (!file.exists())
		{
			return read;
		}
		try (BufferedReader reader = file.openBufferedReader())
		{
			for (String line; (line = reader.readLine()) != null; )
			{
				if (line.trim().isEmpty())
				{
					continue;
				}
				try
				{
					HistoryEntry entry = gson.fromJson(line, HistoryEntry.class);
					// Skip lines this version can't make sense of (e.g. written by a newer version)
					if (entry != null && entry.getKind() != null)
					{
						read.add(entry);
					}
				}
				catch (JsonParseException e)
				{
					log.debug("Five Active: skipping unreadable history line", e);
				}
			}
		}
		read.sort(Comparator.comparingLong(HistoryEntry::getTime));
		return read;
	}

	// ---------------------------------------------------------------- Backups

	/** Saves a copy of the run in the background, unless it's the same as the newest copy. */
	void backup(String stateJson)
	{
		Filepath account = folder;
		if (account != null && stateJson != null)
		{
			onDisk(() -> writeBackup(account, stateJson));
		}
	}

	/** Keeps the newest MAX_BACKUPS. On the background thread. */
	private void writeBackup(Filepath account, String stateJson) throws IOException
	{
		List<Backup> backups = readBackups(account);
		if (!backups.isEmpty() && backups.get(0).getStateJson().equals(stateJson))
		{
			return;
		}
		Filepath dir = account.joinSegment(BACKUP_DIR);
		dir.createDirectories();
		dir.joinSegment(stamp(System.currentTimeMillis()) + ".json").write(stateJson);
		List<Backup> all = readBackups(account);
		for (int i = MAX_BACKUPS; i < all.size(); i++)
		{
			all.get(i).getFile().deleteIfExists();
		}
	}

	/** Reads the account's backups in the background, then hands them (newest first) to done, on that thread. */
	void listBackups(Consumer<List<Backup>> done)
	{
		Filepath account = folder;
		if (account == null)
		{
			done.accept(Collections.emptyList());
			return;
		}
		onDisk(() -> done.accept(readBackups(account)));
	}

	private List<Backup> readBackups(Filepath account) throws IOException
	{
		List<Backup> backups = new ArrayList<>();
		Filepath dir = account.joinSegment(BACKUP_DIR);
		if (!dir.isDirectory())
		{
			return backups;
		}
		List<Filepath> files;
		try (Stream<Filepath> walk = dir.walk(1))
		{
			files = walk.filter(f -> f.getFileName().endsWith(".json")).collect(Collectors.toList());
		}
		for (Filepath file : files)
		{
			try (InputStream in = file.openInputStream())
			{
				long time = new SimpleDateFormat(FILE_TIME).parse(file.getFileName().replace(".json", "")).getTime();
				backups.add(new Backup(file, time, new String(readAll(in), StandardCharsets.UTF_8)));
			}
			catch (Exception e)
			{
				log.debug("Five Active: skipping unreadable backup {}", file, e);
			}
		}
		backups.sort(Comparator.comparingLong(Backup::getTime).reversed());
		return backups;
	}

	/** The account's folder (for "Open backup folder"), or the plugin's when logged out. */
	Filepath folder()
	{
		Filepath account = folder;
		return account != null ? account : root;
	}

	private static String stamp(long time)
	{
		return new SimpleDateFormat(FILE_TIME).format(new Date(time));
	}

	private static byte[] readAll(InputStream in) throws IOException
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		byte[] buffer = new byte[8192];
		for (int n; (n = in.read(buffer)) > 0; )
		{
			out.write(buffer, 0, n);
		}
		return out.toByteArray();
	}

	// ---------------------------------------------------------------- Other files

	/** Writes text to a file the player chose, in the background; done gets the error, or null, on that thread. */
	void writeFile(Filepath file, String text, Consumer<IOException> done)
	{
		onDiskReporting(() -> file.write(text), done);
	}

	/** Reads a file the player chose, in the background; done gets its text (null if it couldn't be read). */
	void readFile(Filepath file, Consumer<String> done)
	{
		onDisk(() ->
		{
			String text = null;
			try (InputStream in = file.openInputStream())
			{
				text = new String(readAll(in), StandardCharsets.UTF_8);
			}
			catch (IOException e)
			{
				log.debug("Five Active: could not read {}", file, e);
			}
			done.accept(text);
		});
	}

	/** Saves a share card picture in the background; done gets where it went, or null, on that thread. */
	void saveShareCard(java.awt.image.BufferedImage image, String name, Consumer<Filepath> done)
	{
		Filepath base = root;
		if (base == null)
		{
			done.accept(null);
			return;
		}
		onDisk(() ->
		{
			Filepath file = null;
			try
			{
				Filepath dir = base.joinSegment(SHARE_DIR);
				dir.createDirectories();
				file = dir.joinSegment(name);
				try (OutputStream out = file.openOutputStream())
				{
					javax.imageio.ImageIO.write(image, "png", out);
				}
			}
			catch (IOException e)
			{
				log.debug("Five Active: could not save the share card", e);
				file = null;
			}
			done.accept(file);
		});
	}

	private void onDiskReporting(IoTask task, Consumer<IOException> done)
	{
		onDisk(() ->
		{
			IOException error = null;
			try
			{
				task.run();
			}
			catch (IOException e)
			{
				error = e;
			}
			done.accept(error);
		});
	}

	// ---------------------------------------------------------------- Save codes

	/** The run and its whole log as one line of text. */
	String saveCode(String stateJson)
	{
		JsonObject code = new JsonObject();
		code.add("state", gson.fromJson(stateJson, JsonElement.class));
		JsonArray history = new JsonArray();
		for (HistoryEntry entry : entries)
		{
			history.add(gson.toJsonTree(entry));
		}
		code.add("history", history);
		try
		{
			ByteArrayOutputStream bytes = new ByteArrayOutputStream();
			try (OutputStream zip = new GZIPOutputStream(bytes))
			{
				zip.write(gson.toJson(code).getBytes(StandardCharsets.UTF_8));
			}
			return CODE_PREFIX + Base64.getEncoder().encodeToString(bytes.toByteArray());
		}
		catch (IOException e)
		{
			throw new IllegalStateException(e);
		}
	}

	/** Reads a pasted save code, or returns null if it isn't one (whitespace and line breaks are ignored). */
	SaveCode readSaveCode(String text)
	{
		String compact = text == null ? "" : text.replaceAll("\\s", "");
		if (!compact.startsWith(CODE_PREFIX))
		{
			return null;
		}
		try
		{
			byte[] zipped = Base64.getDecoder().decode(compact.substring(CODE_PREFIX.length()));
			byte[] json;
			try (InputStream in = new GZIPInputStream(new ByteArrayInputStream(zipped)))
			{
				json = readAll(in);
			}
			JsonObject code = new JsonParser().parse(new String(json, StandardCharsets.UTF_8)).getAsJsonObject();
			JsonElement state = code.get("state");
			if (state == null || !state.isJsonObject())
			{
				return null;
			}
			List<HistoryEntry> history = null;
			if (code.has("history") && code.get("history").isJsonArray())
			{
				history = new ArrayList<>(Arrays.asList(gson.fromJson(code.get("history"), HistoryEntry[].class)));
				history.removeIf(e -> e == null || e.getKind() == null);
			}
			return new SaveCode(gson.toJson(state), history);
		}
		catch (IllegalArgumentException | IOException | IllegalStateException | JsonParseException e)
		{
			log.debug("Five Active: not a valid save code", e);
			return null;
		}
	}
}

package com.bswmagicgaming.fiveactive;

import com.google.common.collect.ImmutableMap;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.client.ui.ColorScheme;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Colours the skills tab: active skills outlined orange, finished ones (waiting for a roll) green, permanently
 * unlocked ones (Hitpoints and 99s) gold with a trim line on 99s, and everything else darkened.
 */
class SkillsTabOverlay extends Overlay
{
	private static final Color INACTIVE_FILTER = new Color(0, 0, 0, 180);
	/** Same orange as "active" in the side panel. */
	private static final Color ACTIVE_OUTLINE = new Color(220, 138, 0);
	/** Finished and waiting for a replacement to be rolled: the side panel's green for done. */
	private static final Color DONE_OUTLINE = ColorScheme.PROGRESS_COMPLETE_COLOR;
	/** Permanently unlocked (Hitpoints, and every skill at 99): gold, like a skillcape. */
	private static final Color PERMANENT_OUTLINE = new Color(255, 200, 40);
	/** The inner trim line on a 99, like a trimmed skillcape. */
	private static final Color TRIM = new Color(255, 236, 150);
	/** Black line around the orange, so it stays crisp against the stone texture. */
	private static final Color ACTIVE_OUTLINE_EDGE = Color.BLACK;

	/** The skills tab lays skills out column by column, so map each widget explicitly. */
	private static final Map<Skill, Integer> SKILL_WIDGETS = ImmutableMap.<Skill, Integer>builder()
		.put(Skill.ATTACK, InterfaceID.Stats.ATTACK)
		.put(Skill.STRENGTH, InterfaceID.Stats.STRENGTH)
		.put(Skill.DEFENCE, InterfaceID.Stats.DEFENCE)
		.put(Skill.RANGED, InterfaceID.Stats.RANGED)
		.put(Skill.PRAYER, InterfaceID.Stats.PRAYER)
		.put(Skill.MAGIC, InterfaceID.Stats.MAGIC)
		.put(Skill.RUNECRAFT, InterfaceID.Stats.RUNECRAFT)
		.put(Skill.CONSTRUCTION, InterfaceID.Stats.CONSTRUCTION)
		.put(Skill.HITPOINTS, InterfaceID.Stats.HITPOINTS)
		.put(Skill.AGILITY, InterfaceID.Stats.AGILITY)
		.put(Skill.HERBLORE, InterfaceID.Stats.HERBLORE)
		.put(Skill.THIEVING, InterfaceID.Stats.THIEVING)
		.put(Skill.CRAFTING, InterfaceID.Stats.CRAFTING)
		.put(Skill.FLETCHING, InterfaceID.Stats.FLETCHING)
		.put(Skill.SLAYER, InterfaceID.Stats.SLAYER)
		.put(Skill.HUNTER, InterfaceID.Stats.HUNTER)
		.put(Skill.MINING, InterfaceID.Stats.MINING)
		.put(Skill.SMITHING, InterfaceID.Stats.SMITHING)
		.put(Skill.FISHING, InterfaceID.Stats.FISHING)
		.put(Skill.COOKING, InterfaceID.Stats.COOKING)
		.put(Skill.FIREMAKING, InterfaceID.Stats.FIREMAKING)
		.put(Skill.WOODCUTTING, InterfaceID.Stats.WOODCUTTING)
		.put(Skill.FARMING, InterfaceID.Stats.FARMING)
		.put(Skill.SAILING, InterfaceID.Stats.SAILING)
		.build();

	private final Client client;
	private final FiveActivePlugin plugin;

	@Inject
	SkillsTabOverlay(Client client, FiveActivePlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		// Draw inside the skills tab, right after its last skill box, instead of on top of every widget.
		// Everything the tab draws later, like the XP hover tooltip, then appears above the dimming.
		setLayer(OverlayLayer.MANUAL);
		drawAfterLayer(InterfaceID.Stats.SAILING);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (plugin.getState() == null || plugin.getState().getSkills().isEmpty() || !plugin.getConfig().dimSkillsTab())
		{
			return null;
		}

		Widget container = client.getWidget(InterfaceID.Stats.UNIVERSE);
		if (container == null || container.isHidden())
		{
			return null;
		}

		// The Total level bar is drawn after this overlay and overlaps the bottom row of skill boxes by a few
		// pixels, so stop each box at the top of the bar to keep the whole outline visible
		Widget total = client.getWidget(InterfaceID.Stats.TOTAL);
		int visibleBottom = total != null && !total.isHidden() ? total.getBounds().y : Integer.MAX_VALUE;

		graphics.setStroke(new BasicStroke(1));
		for (Map.Entry<Skill, Integer> entry : SKILL_WIDGETS.entrySet())
		{
			Widget widget = client.getWidget(entry.getValue());
			if (widget == null || widget.isHidden())
			{
				continue;
			}

			Rectangle bounds = new Rectangle(widget.getBounds());
			if (bounds.y < visibleBottom && bounds.y + bounds.height > visibleBottom)
			{
				bounds.height = visibleBottom - bounds.y;
			}
			Skill skill = entry.getKey();
			float pop = plugin.skillRevealPop(skill);
			if (pop >= 0f)
			{
				drawPop(graphics, bounds, pop, ACTIVE_OUTLINE);
			}
			float done = plugin.completionPop(Category.SKILLS, skill.getName());
			if (done >= 0f)
			{
				drawPop(graphics, bounds, done, DONE_OUTLINE);
			}
			boolean maxed = plugin.isSkillMaxed(skill);
			if (skill == Skill.HITPOINTS || maxed)
			{
				outline(graphics, bounds, PERMANENT_OUTLINE);
				if (maxed)
				{
					// A second, lighter line just inside the gold, like the trim on a trimmed skillcape
					graphics.setColor(TRIM);
					graphics.drawRect(bounds.x + 3, bounds.y + 3, bounds.width - 7, bounds.height - 7);
				}
			}
			else if (plugin.isSkillShownActive(skill))
			{
				outline(graphics, bounds, ACTIVE_OUTLINE);
			}
			else if (plugin.isSkillCompleted(skill))
			{
				outline(graphics, bounds, DONE_OUTLINE);
			}
			else
			{
				graphics.setColor(INACTIVE_FILTER);
				graphics.fill(bounds);
			}
		}
		return null;
	}

	/** Black on the edge, the colour just inside it; both stay within the skill's box. */
	private static void outline(Graphics2D graphics, Rectangle bounds, Color color)
	{
		graphics.setColor(ACTIVE_OUTLINE_EDGE);
		graphics.drawRect(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1);
		graphics.setColor(color);
		graphics.drawRect(bounds.x + 1, bounds.y + 1, bounds.width - 3, bounds.height - 3);
	}

	/**
	 * The pop, same as the overlay, panel and boss pool: a box springs open past the skill's box and settles
	 * back, fading out as it goes. Orange when the skill's reel lands, green when it's finished.
	 */
	private static void drawPop(Graphics2D graphics, Rectangle bounds, float t, Color color)
	{
		float u = t - 1f;
		float spring = 1f + 2.70158f * u * u * u + 1.70158f * u * u; // easeOutBack
		float scale = 0.5f + 0.5f * spring;
		int w = Math.round(bounds.width * scale);
		int h = Math.round(bounds.height * scale);
		int x = (int) Math.round(bounds.getCenterX() - w / 2.0);
		int y = (int) Math.round(bounds.getCenterY() - h / 2.0);
		graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), Math.round(170 * (1f - t))));
		graphics.fillRect(x, y, w, h);
	}
}

package com.bswmagicgaming.fiveactive;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * One active goal (a skill, boss or quest) and how far the player has got with it.
 * A completed slot stays visible (marked done) until the player rolls its replacement.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
class Slot<T>
{
	private T value;
	/** Level-ups for skills, kills for bosses. Unused for quests. */
	private int progress;
	private boolean done;
	/** Shows a "NEW" badge until it expires (see {@link Rules#NEW_BADGE_SECONDS}) or the player makes progress. */
	private boolean fresh;
	/** When this slot was rolled (epoch millis), for expiring the NEW badge. */
	private long rolledAt;
	/** When this slot was completed (epoch millis), or 0 if it isn't or it was before this was kept. */
	private long doneAt;
	/** Skills only: level-ups this slot needs (fewer than 5 for the last stretch to 99), or 0 for the usual 5. */
	private int goal;

	static <T> Slot<T> of(T value)
	{
		return new Slot<>(value, 0, false, true, System.currentTimeMillis(), 0, 0);
	}
}

package com.bswmagicgaming.fiveactive;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * "TIER X UNLOCKED!" across the middle of the game view when a boss tier is claimed, in the panel's pixel
 * letters: it springs in, holds for a moment with how many bosses joined, then shrinks away.
 */
class TierBannerOverlay extends Overlay
{
	private static final int POP_IN_MS = 450;
	private static final int POP_OUT_MS = 300;
	/** Space between the big title and the line under it. */
	private static final int SUBTITLE_GAP = 14;
	private static final Color GOLD = new Color(255, 200, 40);
	private static final Color GOLD_SHADOW = new Color(140, 90, 0);

	private final Client client;
	private volatile long shownAt;
	private volatile BufferedImage title;
	private volatile String subtitle;
	private volatile int tier;
	/** When the banner starts popping out (it's on screen for as long as the tier's fireworks). */
	private volatile int holdUntilMs;

	@Inject
	TierBannerOverlay(Client client)
	{
		this.client = client;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGHEST);
	}

	/** Shows the banner for tier (an index into BossTiers.TIERS). Any thread. */
	void show(int tier, int bossCount)
	{
		this.tier = tier;
		title = titleImage(tier, NavIcon.WHITE, NavIcon.WHITE_SHADOW);
		String joined = bossCount == 0 ? "Its bosses need a quest or Slayer level first"
			: bossCount + " new " + (bossCount == 1 ? "boss joins" : "bosses join") + " the pool";
		subtitle = TierFanfare.isLast(tier) ? "Every tier unlocked!  " + joined : joined;
		holdUntilMs = TierFanfare.celebrateMs(tier) - POP_OUT_MS;
		shownAt = System.currentTimeMillis();
	}

	/** "TIER X " in gold, then "UNLOCKED!" in the given colour, at the tier's size. */
	private static BufferedImage titleImage(int tier, Color unlocked, Color unlockedShadow)
	{
		return NavIcon.outline(PixelFont.render(TierFanfare.bannerScale(tier),
			new PixelFont.Run("TIER " + (tier + 1) + " ", GOLD, GOLD_SHADOW),
			new PixelFont.Run("UNLOCKED!", unlocked, unlockedShadow)));
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		long start = shownAt;
		BufferedImage image = title;
		if (start == 0 || image == null)
		{
			return null;
		}
		long t = System.currentTimeMillis() - start;
		int holdUntil = holdUntilMs;
		int showTier = tier;
		if (TierFanfare.isLast(showTier))
		{
			// The last tier: "UNLOCKED!" shimmers through warm colours, gold to orange to red and back (no blue:
			// that's the credit's colour)
			float wave = 0.5f + 0.5f * (float) Math.sin(t / 300.0);
			Color shimmer = Color.getHSBColor(0.15f * wave, 0.7f, 1f);
			image = titleImage(showTier, shimmer, shimmer.darker().darker());
		}
		if (t > holdUntil + POP_OUT_MS)
		{
			shownAt = 0;
			return null;
		}

		float scale;
		if (t < POP_IN_MS)
		{
			// Springs in past full size and settles (easeOutBack)
			float u = t / (float) POP_IN_MS - 1f;
			scale = 0.2f + 0.8f * (1f + 3.5f * u * u * u + 2.5f * u * u);
		}
		else if (t < holdUntil)
		{
			scale = 1f;
		}
		else
		{
			float out = (t - holdUntil) / (float) POP_OUT_MS;
			scale = 1f - out * out;
		}
		if (scale <= 0f)
		{
			return null;
		}

		int cx = client.getViewportXOffset() + client.getViewportWidth() / 2;
		// A quarter of the way down the game view: up out of the way of your character
		int cy = client.getViewportYOffset() + client.getViewportHeight() / 4;
		Graphics2D g2 = (Graphics2D) g.create();
		// Nearest neighbour: the pixel letters stay crisp at any size
		g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		int w = Math.round(image.getWidth() * scale);
		int h = Math.round(image.getHeight() * scale);
		if (TierFanfare.glows(showTier) && t >= POP_IN_MS && t < holdUntil)
		{
			// Tier 4 and up: a soft gold glow pulses behind the letters
			float pulse = 0.5f + 0.5f * (float) Math.sin(t / 220.0);
			g2.setColor(new Color(GOLD.getRed(), GOLD.getGreen(), GOLD.getBlue(), Math.round(40 + 60 * pulse)));
			int grow = Math.round(6 + 6 * pulse);
			g2.fillRoundRect(cx - w / 2 - grow, cy - h / 2 - grow, w + grow * 2, h + grow * 2, 18, 18);
		}
		g2.drawImage(image, cx - w / 2, cy - h / 2, w, h, null);

		if (t >= POP_IN_MS && t < holdUntil)
		{
			Font font = FontManager.getRunescapeBoldFont();
			g2.setFont(font);
			FontMetrics fm = g2.getFontMetrics();
			String text = subtitle;
			int x = cx - fm.stringWidth(text) / 2;
			// A clear gap under the big letters, so the two lines don't crowd each other
			int y = cy + image.getHeight() / 2 + SUBTITLE_GAP + fm.getAscent();
			g2.setColor(Color.BLACK);
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					if (dx != 0 || dy != 0)
					{
						g2.drawString(text, x + dx, y + dy);
					}
				}
			}
			g2.setColor(Color.WHITE);
			g2.drawString(text, x, y);
		}
		g2.dispose();
		return null;
	}
}

package com.bswmagicgaming.fiveactive;

import net.runelite.api.gameval.SpotanimID;

/**
 * How big each boss tier unlock's celebration is. Every tier is flashier than the last: longer trembling,
 * harder shaking, bigger fireworks, a bigger banner that stays up longer, more booms. Tier 5 (the last one)
 * gets everything. Indexes are into BossTiers.TIERS (1 = tier 2, the first tier ever unlocked).
 */
final class TierFanfare
{
	/** How long the tier's icons tremble before the first pop. */
	private static final int[] TREMBLE_MS = {1350, 1350, 1650, 1950, 2400};
	/** How far (pixels) the icons shake at full strength. */
	private static final int[] SHAKE_PX = {2, 2, 2, 3, 3};
	/** How long the banner and fireworks stay up. */
	private static final int[] CELEBRATE_MS = {3500, 3500, 5000, 6500, 9000};
	/** Pixel size of the banner's letters. */
	private static final int[] BANNER_SCALE = {3, 3, 4, 4, 5};
	/** How many times the finale sound booms (a little apart). */
	private static final int[] FINALE_BOOMS = {1, 1, 1, 2, 3};
	/** Fireworks (spot animations, played together): normal level-up, level 99, max total level, then max total and 99 layered. */
	private static final int[][] EFFECTS = {
		{SpotanimID.LEVELUP_ANIM},
		{SpotanimID.LEVELUP_ANIM},
		{SpotanimID.LEVELUP_99_ANIM},
		{SpotanimID.LEVELUP_MAX},
		{SpotanimID.LEVELUP_MAX, SpotanimID.LEVELUP_99_ANIM},
	};

	/** Sound effect IDs for the ceremony: the Unlock button's rumble, each boss popping in, and the finale. */
	static final int RUMBLE_SOUND = 1930;
	static final int POP_SOUND = 3929;
	static final int FINALE_SOUND = 3813;

	static java.util.List<Integer> effects(int tier)
	{
		java.util.List<Integer> effects = new java.util.ArrayList<>();
		for (int id : EFFECTS[clamp(tier)])
		{
			effects.add(id);
		}
		return effects;
	}

	static int trembleMs(int tier)
	{
		return TREMBLE_MS[clamp(tier)];
	}

	static int shakePx(int tier)
	{
		return SHAKE_PX[clamp(tier)];
	}

	static int celebrateMs(int tier)
	{
		return CELEBRATE_MS[clamp(tier)];
	}

	static int bannerScale(int tier)
	{
		return BANNER_SCALE[clamp(tier)];
	}

	static int finaleBooms(int tier)
	{
		return FINALE_BOOMS[clamp(tier)];
	}

	/** The last tier: the banner shimmers and says every boss is unlocked. */
	static boolean isLast(int tier)
	{
		return tier >= BossTiers.TIERS.size() - 1;
	}

	/** Tier 4 and up: the banner's letters get a pulsing gold glow. */
	static boolean glows(int tier)
	{
		return tier >= 3;
	}

	private static int clamp(int tier)
	{
		return Math.max(0, Math.min(tier, TREMBLE_MS.length - 1));
	}

	private TierFanfare()
	{
	}
}

